// UpscaleStrategy.swift
// Defines upscale strategy.
//

import Metal

// MARK: - UpscaleStrategy

/// Upscale strategy resolved per device at runtime.
///
/// Only spatial (single-frame) upscalers are eligible: frame interpolation adds at least one
/// stream frame of latency by construction, which is unacceptable for interactive gameplay.
///
/// Default order (highest → lowest):
///   1. `metalFXSpatial`     — MTLFXSpatialScaler, GPU-only and available on every tvOS 27 Apple TV
///   2. `vtSuperResolution`  — VTLowLatencySuperResolutionScaler (device support is runtime-probed)
///   3. `passthrough`        — no processing; the display target scales the frame
public enum UpscaleStrategy: Equatable, Sendable {
    case metalFXSpatial
    case vtSuperResolution(scaleFactor: Float)
    case passthrough
}

// MARK: - UpscalerPreference

/// Which upscaler the ladder should try first when more than one is eligible.
public enum UpscalerPreference: String, CaseIterable, Sendable {
    /// MetalFX spatial first, VideoToolbox low-latency super resolution second.
    case automatic
    case metalFXSpatial
    case vtSuperResolution
}

// MARK: - UpscaleCapabilityProbing

/// Injectable interface for querying device upscale capabilities.
/// Concrete implementations: `LiveUpscaleCapabilityProbe` and test mocks.
public protocol UpscaleCapabilityProbing: Sendable {
    /// Returns the supported VT super-resolution scale factors for the given source dimensions,
    /// or empty when LLSR is unavailable on this device.
    func vtSuperResolutionScaleFactors(sourceW: Int, sourceH: Int) -> [Float]

    /// Returns `true` when the device supports `MTLFXSpatialScaler`.
    func supportsMetalFXSpatial(device: any MTLDevice) -> Bool
}

// UpscaleCapabilityResolver.swift
// Defines upscale capability resolver.
//

import Foundation
import Metal

// MARK: - UpscaleCapabilityResolver

public struct UpscaleCandidateResolution: Equatable, Sendable {
    public let candidates: [UpscaleStrategy]
    public let skippedRungReasons: [String: String]

    public init(
        candidates: [UpscaleStrategy],
        skippedRungReasons: [String: String]
    ) {
        self.candidates = candidates
        self.skippedRungReasons = skippedRungReasons
    }
}

/// Resolves the eligible upscale strategies for the current device and source dimensions.
///
/// The resolver is stateless and cheap to call — run it whenever the source resolution
/// changes, not per frame.
public struct UpscaleCapabilityResolver: Sendable {

    public let probe: any UpscaleCapabilityProbing

    public init(probe: any UpscaleCapabilityProbing) {
        self.probe = probe
    }

    /// Returns the highest-priority `UpscaleStrategy` available for the given device and dimensions.
    ///
    /// - Returns `.passthrough` when `source >= target` in both dimensions or no upscaler is available.
    public func resolve(
        device: any MTLDevice,
        sourceW: Int, sourceH: Int,
        targetW: Int, targetH: Int,
        preference: UpscalerPreference = .automatic
    ) -> UpscaleStrategy {
        resolveCandidateResolution(
            device: device,
            sourceW: sourceW,
            sourceH: sourceH,
            targetW: targetW,
            targetH: targetH,
            preference: preference
        ).candidates.first ?? .passthrough
    }

    /// Returns all eligible strategies in descending priority order for the given device and dimensions.
    public func resolveCandidates(
        device: any MTLDevice,
        sourceW: Int,
        sourceH: Int,
        targetW: Int,
        targetH: Int,
        preference: UpscalerPreference = .automatic
    ) -> [UpscaleStrategy] {
        resolveCandidateResolution(
            device: device,
            sourceW: sourceW,
            sourceH: sourceH,
            targetW: targetW,
            targetH: targetH,
            preference: preference
        ).candidates
    }

    public func resolveCandidateResolution(
        device: (any MTLDevice)?,
        sourceW: Int,
        sourceH: Int,
        targetW: Int,
        targetH: Int,
        preference: UpscalerPreference = .automatic
    ) -> UpscaleCandidateResolution {
        guard sourceW > 0, sourceH > 0, targetW > 0, targetH > 0 else {
            return invalidDimensionsResolution()
        }

        guard targetW > sourceW || targetH > sourceH else {
            return UpscaleCandidateResolution(candidates: [.passthrough], skippedRungReasons: [:])
        }

        var skippedRungReasons: [String: String] = [:]
        let metalFX = metalFXCandidate(device: device, skippedRungReasons: &skippedRungReasons)
        let superResolution = superResolutionCandidate(
            sourceW: sourceW,
            sourceH: sourceH,
            targetW: targetW,
            targetH: targetH,
            skippedRungReasons: &skippedRungReasons
        )

        let ordered: [UpscaleStrategy?]
        switch preference {
        case .automatic, .metalFXSpatial:
            ordered = [metalFX, superResolution]
        case .vtSuperResolution:
            ordered = [superResolution, metalFX]
        }

        return UpscaleCandidateResolution(
            candidates: ordered.compactMap { $0 } + [.passthrough],
            skippedRungReasons: skippedRungReasons
        )
    }

    private func invalidDimensionsResolution() -> UpscaleCandidateResolution {
        let invalidDimensionReason = "invalid source or target dimensions"
        return UpscaleCandidateResolution(
            candidates: [.passthrough],
            skippedRungReasons: [
                "llsr": invalidDimensionReason,
                "metalfx": invalidDimensionReason
            ]
        )
    }

    private func metalFXCandidate(
        device: (any MTLDevice)?,
        skippedRungReasons: inout [String: String]
    ) -> UpscaleStrategy? {
        guard let device else {
            skippedRungReasons["metalfx"] = "Metal device unavailable"
            return nil
        }
        guard probe.supportsMetalFXSpatial(device: device) else {
            skippedRungReasons["metalfx"] = "unsupported on this device"
            return nil
        }
        return .metalFXSpatial
    }

    private func superResolutionCandidate(
        sourceW: Int,
        sourceH: Int,
        targetW: Int,
        targetH: Int,
        skippedRungReasons: inout [String: String]
    ) -> UpscaleStrategy? {
        let scaleFactors = probe.vtSuperResolutionScaleFactors(sourceW: sourceW, sourceH: sourceH).sorted()
        let fittingScaleFactors = scaleFactors.filter {
            scaledDimensionsFitWithinTarget(
                sourceW: sourceW,
                sourceH: sourceH,
                scaleFactor: $0,
                targetW: targetW,
                targetH: targetH
            )
        }

        if let scaleFactor = fittingScaleFactors.max() {
            return .vtSuperResolution(scaleFactor: scaleFactor)
        }
        if scaleFactors.isEmpty {
            skippedRungReasons["llsr"] = "unsupported for \(sourceW)x\(sourceH)"
        } else {
            skippedRungReasons["llsr"] = "supportedScaleFactors=\(scaleFactorListDescription(scaleFactors)) overshoot target \(targetW)x\(targetH)"
        }
        return nil
    }

    private func scaledDimensionsFitWithinTarget(
        sourceW: Int,
        sourceH: Int,
        scaleFactor: Float,
        targetW: Int,
        targetH: Int
    ) -> Bool {
        let scaledWidth = Int((Double(sourceW) * Double(scaleFactor)).rounded())
        let scaledHeight = Int((Double(sourceH) * Double(scaleFactor)).rounded())
        return scaledWidth <= targetW && scaledHeight <= targetH
    }

    private func scaleFactorListDescription(_ factors: [Float]) -> String {
        "[" + factors.map { formattedScale(Double($0)) }.joined(separator: ", ") + "]"
    }

    private func formattedScale(_ value: Double) -> String {
        let rounded = (value * 100).rounded() / 100
        if abs(rounded.rounded() - rounded) < 0.001 {
            return String(Int(rounded.rounded()))
        }
        return String(format: "%.2f", rounded)
    }
}

// LiveUpscaleCapabilityProbe.swift
// Defines live upscale capability probe.
//

import Metal
#if canImport(MetalFX)
import MetalFX
#endif
import VideoToolbox
import OSLog

private let log = Logger(subsystem: "VideoRenderingKit", category: "CapabilityProbe")

// MARK: - LiveUpscaleCapabilityProbe

/// Real hardware capability probe used in production.
///
/// All checks are lightweight (no GPU work, no VT session creation beyond what the API
/// requires for a capability query). Safe to call on any thread.
public struct LiveUpscaleCapabilityProbe: UpscaleCapabilityProbing {

    public init() {}

    // MARK: VT Super Resolution
    // VTLowLatencySuperResolutionScalerConfiguration is real-device only (no simulator stub).

    public func vtSuperResolutionScaleFactors(sourceW: Int, sourceH: Int) -> [Float] {
#if !targetEnvironment(simulator)
        guard VTLowLatencySuperResolutionScalerConfiguration.isSupported else {
            log.debug("LLSR: not supported on this device")
            return []
        }
        let factors = VTLowLatencySuperResolutionScalerConfiguration
            .supportedScaleFactors(frameWidth: sourceW, frameHeight: sourceH)
            .map { Float($0) }
        log.debug("LLSR supported scale factors for \(sourceW)×\(sourceH): \(factors)")
        return factors
#else
        return []
#endif
    }

    // MARK: MetalFX Spatial

    public func supportsMetalFXSpatial(device: any MTLDevice) -> Bool {
        #if canImport(MetalFX)
        let supported = MTLFXSpatialScalerDescriptor.supportsDevice(device)
        log.debug("MetalFX spatial supported: \(supported)")
        return supported
        #else
        return false
        #endif
    }
}

// RenderLadderPlanner.swift
// Defines render ladder planner.
//

import Metal

/// Chooses which non-upscaled floor the renderer should fall back to when higher rungs fail.
public enum RenderLadderFloorBehavior: String, CaseIterable, Sendable {
    case sampleFloor
    case metalFloor
}

/// Pixel dimensions for a source frame, processing target, or display target in the ladder plan.
public struct RenderLadderDimensions: Equatable, Sendable {
    public let width: Int
    public let height: Int

    public init(width: Int, height: Int) {
        self.width = width
        self.height = height
    }
}

/// Represents one rendering or upscaling path the app can attempt for a stream.
public enum RenderLadderRung: Hashable, Sendable {
    case sampleBuffer
    case vtSuperResolution(scaleFactor: Float)
    case metalFXSpatial
    case passthrough

    /// Stable diagnostics/export name used by renderer telemetry and fallback tracking.
    public var rawName: String {
        switch self {
        case .sampleBuffer:
            return "sampleBuffer"
        case .vtSuperResolution:
            return "llsr"
        case .metalFXSpatial:
            return "metalfx"
        case .passthrough:
            return "passthrough"
        }
    }

    /// Whether the rung is presented by the Metal renderer (as opposed to the sample-buffer layer).
    public var usesMetalOutput: Bool {
        switch self {
        case .metalFXSpatial, .passthrough:
            return true
        case .sampleBuffer, .vtSuperResolution:
            return false
        }
    }
}

/// Describes the active rung, fallback floor, and candidate ladder for a renderer session.
public struct RenderLadderPlan: Equatable, Sendable {
    public let activeRung: RenderLadderRung
    public let sourceDimensions: RenderLadderDimensions
    public let displayTargetDimensions: RenderLadderDimensions
    public let desiredProcessingTarget: RenderLadderDimensions
    public let eligibleRungs: [RenderLadderRung]
    public let skippedRungReasons: [String: String]
    public let floorRung: RenderLadderRung

    public init(
        activeRung: RenderLadderRung,
        sourceDimensions: RenderLadderDimensions,
        displayTargetDimensions: RenderLadderDimensions,
        desiredProcessingTarget: RenderLadderDimensions,
        eligibleRungs: [RenderLadderRung],
        skippedRungReasons: [String: String] = [:],
        floorRung: RenderLadderRung
    ) {
        self.activeRung = activeRung
        self.sourceDimensions = sourceDimensions
        self.displayTargetDimensions = displayTargetDimensions
        self.desiredProcessingTarget = desiredProcessingTarget
        self.eligibleRungs = eligibleRungs
        self.skippedRungReasons = skippedRungReasons
        self.floorRung = floorRung
    }
}

/// Translates capability resolution into an ordered render ladder the app can walk during failures.
public struct RenderLadderPlanner: Sendable {
    public let resolver: UpscaleCapabilityResolver

    public init(resolver: UpscaleCapabilityResolver) {
        self.resolver = resolver
    }

    /// Builds the initial ladder from source dimensions, display target, and current device capability.
    public func makePlan(
        device: (any MTLDevice)?,
        sourceW: Int,
        sourceH: Int,
        targetW: Int,
        targetH: Int,
        upscalingEnabled: Bool,
        floorBehavior: RenderLadderFloorBehavior,
        preference: UpscalerPreference = .automatic
    ) -> RenderLadderPlan {
        let sourceDimensions = RenderLadderDimensions(
            width: max(1, sourceW),
            height: max(1, sourceH)
        )
        let displayTargetDimensions = resolvedDisplayTargetDimensions(
            sourceDimensions: sourceDimensions,
            targetW: targetW,
            targetH: targetH
        )
        let desiredProcessingTarget = desiredProcessingTarget(
            sourceDimensions: sourceDimensions,
            displayTargetDimensions: displayTargetDimensions
        )

        guard upscalingEnabled else {
            return RenderLadderPlan(
                activeRung: .sampleBuffer,
                sourceDimensions: sourceDimensions,
                displayTargetDimensions: displayTargetDimensions,
                desiredProcessingTarget: desiredProcessingTarget,
                eligibleRungs: [],
                skippedRungReasons: [:],
                floorRung: .sampleBuffer
            )
        }

        let resolution = resolver.resolveCandidateResolution(
            device: device,
            sourceW: sourceDimensions.width,
            sourceH: sourceDimensions.height,
            targetW: desiredProcessingTarget.width,
            targetH: desiredProcessingTarget.height,
            preference: preference
        )

        let floorRung: RenderLadderRung = floorBehavior == .metalFloor && device != nil ? .passthrough : .sampleBuffer
        var candidates = resolution.candidates.compactMap(Self.ladderRung(from:)).filter { $0 != .passthrough }
        var skippedRungReasons = resolution.skippedRungReasons
        if floorBehavior == .metalFloor && device == nil {
            skippedRungReasons["passthrough"] = "Metal device unavailable"
        }
        if floorRung == .passthrough {
            candidates.append(.passthrough)
        }

        return RenderLadderPlan(
            activeRung: .sampleBuffer,
            sourceDimensions: sourceDimensions,
            displayTargetDimensions: displayTargetDimensions,
            desiredProcessingTarget: desiredProcessingTarget,
            eligibleRungs: candidates,
            skippedRungReasons: skippedRungReasons,
            floorRung: floorRung
        )
    }

    /// Returns the next eligible rung that has not already been marked dead by prior failures.
    public func nextCandidate(
        in plan: RenderLadderPlan,
        deadRungs: Set<RenderLadderRung>
    ) -> RenderLadderRung? {
        plan.eligibleRungs.first { !deadRungs.contains($0) }
    }

    /// Marks one rung as dead after a runtime failure so later selection skips it.
    public func deadRungsAfterFailure(
        _ failedRung: RenderLadderRung,
        existingDeadRungs: Set<RenderLadderRung>
    ) -> Set<RenderLadderRung> {
        var updated = existingDeadRungs
        updated.insert(failedRung)
        return updated
    }

    /// Increments the retry budget consumed by a rung after one failed activation attempt.
    public func failureCountsAfterFailure(
        _ failedRung: RenderLadderRung,
        existingFailureCounts: [RenderLadderRung: Int]
    ) -> [RenderLadderRung: Int] {
        var updated = existingFailureCounts
        updated[failedRung, default: 0] += 1
        return updated
    }

    /// Converts per-rung failure counts into the set that should no longer be retried.
    public func deadRungs(
        from failureCounts: [RenderLadderRung: Int],
        maxFailures: Int
    ) -> Set<RenderLadderRung> {
        let threshold = max(1, maxFailures)
        return Set(
            failureCounts.compactMap { rung, count in
                count >= threshold ? rung : nil
            }
        )
    }

    private static func ladderRung(from strategy: UpscaleStrategy) -> RenderLadderRung? {
        switch strategy {
        case .vtSuperResolution(let scaleFactor):
            return .vtSuperResolution(scaleFactor: scaleFactor)
        case .metalFXSpatial:
            return .metalFXSpatial
        case .passthrough:
            return .passthrough
        }
    }

    private func resolvedDisplayTargetDimensions(
        sourceDimensions: RenderLadderDimensions,
        targetW: Int,
        targetH: Int
    ) -> RenderLadderDimensions {
        guard targetW > 0, targetH > 0 else {
            return sourceDimensions
        }
        return RenderLadderDimensions(width: targetW, height: targetH)
    }

    /// Fits processing dimensions to the display target while preserving the source aspect ratio.
    public func desiredProcessingTarget(
        sourceDimensions: RenderLadderDimensions,
        displayTargetDimensions: RenderLadderDimensions
    ) -> RenderLadderDimensions {
        let widthScale = Double(displayTargetDimensions.width) / Double(sourceDimensions.width)
        let heightScale = Double(displayTargetDimensions.height) / Double(sourceDimensions.height)
        let scale = min(widthScale, heightScale)
        guard scale.isFinite, scale > 0 else {
            return sourceDimensions
        }

        let fittedWidth = max(1, min(displayTargetDimensions.width, Int((Double(sourceDimensions.width) * scale).rounded(.down))))
        let fittedHeight = max(1, min(displayTargetDimensions.height, Int((Double(sourceDimensions.height) * scale).rounded(.down))))
        return RenderLadderDimensions(width: fittedWidth, height: fittedHeight)
    }
}

// UpscaleCapabilityResolverTests.swift
// Exercises upscale capability resolver behavior.
//

import Metal
import Testing
@testable import VideoRenderingKit

struct MockUpscaleCapabilityProbe: UpscaleCapabilityProbing {
    var scaleFactors: [Float] = []
    var metalFX: Bool = false

    func vtSuperResolutionScaleFactors(sourceW: Int, sourceH: Int) -> [Float] { scaleFactors }
    func supportsMetalFXSpatial(device: any MTLDevice) -> Bool { metalFX }
}

@Suite struct UpscaleCapabilityResolverTests {
    let device: any MTLDevice = MTLCreateSystemDefaultDevice()!

    func makeResolver(_ probe: MockUpscaleCapabilityProbe) -> UpscaleCapabilityResolver {
        UpscaleCapabilityResolver(probe: probe)
    }

    @Test func noUpscaleNeeded_returnsPassthrough() {
        let resolver = makeResolver(MockUpscaleCapabilityProbe(scaleFactors: [2.0], metalFX: true))
        let result = resolver.resolve(device: device, sourceW: 1920, sourceH: 1080, targetW: 1920, targetH: 1080)
        #expect(result == .passthrough)
    }

    @Test func sourceLargerThanTarget_passthrough() {
        let resolver = makeResolver(MockUpscaleCapabilityProbe(scaleFactors: [2.0], metalFX: true))
        let result = resolver.resolve(device: device, sourceW: 3840, sourceH: 2160, targetW: 1920, targetH: 1080)
        #expect(result == .passthrough)
    }

    @Test func allUnavailable_returnsPassthrough() {
        let resolver = makeResolver(MockUpscaleCapabilityProbe())
        let result = resolver.resolve(device: device, sourceW: 1920, sourceH: 1080, targetW: 3840, targetH: 2160)
        #expect(result == .passthrough)
    }

    @Test func onlyMetalFX_returnsMetalFXSpatial() {
        let resolver = makeResolver(MockUpscaleCapabilityProbe(metalFX: true))
        let result = resolver.resolve(device: device, sourceW: 1920, sourceH: 1080, targetW: 3840, targetH: 2160)
        #expect(result == .metalFXSpatial)
    }

    @Test func automaticPrefersMetalFXOverLLSR() {
        let resolver = makeResolver(MockUpscaleCapabilityProbe(scaleFactors: [2.0], metalFX: true))
        let result = resolver.resolveCandidates(device: device, sourceW: 1920, sourceH: 1080, targetW: 3840, targetH: 2160)
        #expect(result == [.metalFXSpatial, .vtSuperResolution(scaleFactor: 2.0), .passthrough])
    }

    @Test func vtPreferencePutsLLSRFirst() {
        let resolver = makeResolver(MockUpscaleCapabilityProbe(scaleFactors: [2.0], metalFX: true))
        let result = resolver.resolveCandidates(
            device: device,
            sourceW: 1920,
            sourceH: 1080,
            targetW: 3840,
            targetH: 2160,
            preference: .vtSuperResolution
        )
        #expect(result == [.vtSuperResolution(scaleFactor: 2.0), .metalFXSpatial, .passthrough])
    }

    @Test func vtPreferenceFallsBackToMetalFXWhenLLSRUnavailable() {
        let resolver = makeResolver(MockUpscaleCapabilityProbe(metalFX: true))
        let result = resolver.resolve(
            device: device,
            sourceW: 1920,
            sourceH: 1080,
            targetW: 3840,
            targetH: 2160,
            preference: .vtSuperResolution
        )
        #expect(result == .metalFXSpatial)
    }

    @Test func llsrSelectsLargestScaleFactorThatFitsTarget() {
        let resolver = makeResolver(MockUpscaleCapabilityProbe(scaleFactors: [1.25, 1.5, 2.0]))
        let result = resolver.resolve(device: device, sourceW: 1280, sourceH: 720, targetW: 1920, targetH: 1080)
        #expect(result == .vtSuperResolution(scaleFactor: 1.5))
    }

    @Test func resolveCandidateResolution_reportsSkippedReasons() {
        let resolver = makeResolver(MockUpscaleCapabilityProbe(scaleFactors: [2.0]))
        let result = resolver.resolveCandidateResolution(
            device: nil,
            sourceW: 1280,
            sourceH: 720,
            targetW: 1920,
            targetH: 1080
        )

        #expect(result.candidates == [.passthrough])
        #expect(result.skippedRungReasons["llsr"] == "supportedScaleFactors=[2] overshoot target 1920x1080")
        #expect(result.skippedRungReasons["metalfx"] == "Metal device unavailable")
    }
}

