//
//  CASShader.metal
//  Northstar
//
//  Metal kernels for the video pipeline:
//    - nv12ToBGRA: NV12 → BGRA compute conversion at source resolution (input for MetalFX spatial).
//    - nv12PassthroughVertex/Fragment: NV12 → drawable render pass with bilinear sampling
//      (the passthrough rung and the warm-up path while a scaler is being built).
//  Handles both full-range (420f) and limited-range (420v) input; BT.709 matrix.
//
//  Input:
//    texture(0)  yPlane    — R8Unorm,  full-resolution luma (Y plane of NV12)
//    texture(1)  cbcrPlane — RG8Unorm, half-resolution chroma (CbCr plane of NV12)
//    buffer(2)   isFullRange — uint32, 1 = 420f (full range), 0 = 420v (limited range)
//
//  Output:
//    texture(2)  output    — BGRA8Unorm (compute) / drawable color attachment (render)
//

#include <metal_stdlib>
using namespace metal;

// MARK: - NV12 → RGB (BT.709, range-aware)
//
// fullRange = true  → 420f: Y in [0,1] maps to [0,255], UV centre-only offset.
// fullRange = false → 420v: Y in [0,1] maps to [16,235] (studio swing). This is what the
// patched VideoToolbox decoder emits on tvOS (Tools/webrtc-build/patches/0012).
static float3 nv12ToRGB(float y, float2 cbcr, bool fullRange) {
    float yS, cb, cr;
    if (fullRange) {
        yS = y;
        cb = cbcr.x - 128.0 / 255.0;
        cr = cbcr.y - 128.0 / 255.0;
    } else {
        yS = (y     - 16.0  / 255.0) * (255.0 / 219.0);
        cb = (cbcr.x - 128.0 / 255.0) * (255.0 / 224.0);
        cr = (cbcr.y - 128.0 / 255.0) * (255.0 / 224.0);
    }

    float r = yS                + 1.5748 * cr;
    float g = yS - 0.1873 * cb - 0.4681 * cr;
    float b = yS + 1.8556 * cb;

    return clamp(float3(r, g, b), 0.0, 1.0);
}

constexpr sampler chromaSampler(coord::normalized, address::clamp_to_edge, filter::linear);

// MARK: - Compute conversion (MetalFX input)

kernel void nv12ToBGRA(
    texture2d<float, access::read>   yPlane      [[texture(0)]],
    texture2d<float, access::sample> cbcrPlane   [[texture(1)]],
    texture2d<float, access::write>  output      [[texture(2)]],
    constant uint32_t               &isFullRange  [[buffer(2)]],
    uint2 gid [[thread_position_in_grid]]
) {
    if (gid.x >= output.get_width() || gid.y >= output.get_height()) { return; }

    float  y    = yPlane.read(gid).r;
    // Bilinear chroma reconstruction at the luma sample position (centre-sited 4:2:0).
    float2 uv   = (float2(gid) + 0.5) / float2(output.get_width(), output.get_height());
    float2 cbcr = cbcrPlane.sample(chromaSampler, uv).rg;

    float3 rgb = nv12ToRGB(y, cbcr, isFullRange != 0);
    output.write(float4(rgb, 1.0), gid);
}

// MARK: - Passthrough render pass (NV12 → drawable)

struct PassthroughVertexOut {
    float4 position [[position]];
    float2 uv;
};

// Fullscreen triangle; no vertex buffer needed.
vertex PassthroughVertexOut nv12PassthroughVertex(uint vertexID [[vertex_id]]) {
    PassthroughVertexOut out;
    float2 uv = float2((vertexID << 1) & 2, vertexID & 2);
    out.position = float4(uv * float2(2.0, -2.0) + float2(-1.0, 1.0), 0.0, 1.0);
    out.uv = uv;
    return out;
}

fragment float4 nv12PassthroughFragment(
    PassthroughVertexOut in [[stage_in]],
    texture2d<float, access::sample> yPlane    [[texture(0)]],
    texture2d<float, access::sample> cbcrPlane [[texture(1)]],
    constant uint32_t               &isFullRange [[buffer(2)]]
) {
    float  y    = yPlane.sample(chromaSampler, in.uv).r;
    float2 cbcr = cbcrPlane.sample(chromaSampler, in.uv).rg;
    return float4(nv12ToRGB(y, cbcr, isFullRange != 0), 1.0);
}

// RendererContainerView.swift
// Defines the renderer container view used in the Streaming / UIKitAdapters surface.
//

#if WEBRTC_AVAILABLE && canImport(UIKit) && canImport(Metal)
import UIKit
import QuartzCore

/// UIKit host for the Metal renderer's `CAMetalLayer`.
///
/// The layer is configured once here; per-frame work happens on the renderer's own thread,
/// which only ever touches `drawableSize`, `nextDrawable()`, and the display link.
final class MetalVideoLayerView: UIView {
    override class var layerClass: AnyClass { CAMetalLayer.self }

    var metalLayer: CAMetalLayer {
        layer as! CAMetalLayer
    }

    override init(frame: CGRect) {
        super.init(frame: frame)
        isOpaque = true
        backgroundColor = .black
        isUserInteractionEnabled = false
        let metalLayer = self.metalLayer
        metalLayer.pixelFormat = .bgra8Unorm
        metalLayer.isOpaque = true
        // Compute and MetalFX both write straight into the drawable; that needs
        // more than render-target usage.
        metalLayer.framebufferOnly = false
        // Two drawables keep queueing latency to one frame; the display-link pacing never
        // holds more than one drawable at a time.
        metalLayer.maximumDrawableCount = 2
        metalLayer.contentsGravity = .resizeAspect
        metalLayer.backgroundColor = UIColor.black.cgColor
    }

    required init?(coder: NSCoder) {
        fatalError("init(coder:) is not supported")
    }
}

final class RendererContainerView: UIView {
    weak var metalView: MetalVideoLayerView?
    weak var sampleBufferView: SampleBufferDisplayView?
    private var didLogFirstLayout = false

    override func layoutSubviews() {
        super.layoutSubviews()
        if let metalView {
            metalView.frame = bounds
        }
        if let sampleBufferView {
            sampleBufferView.frame = bounds
            sampleBufferView.setNeedsLayout()
            sampleBufferView.layoutIfNeeded()
        }
        if !didLogFirstLayout, window != nil {
            didLogFirstLayout = true
            let metalWidth = Int(metalView?.bounds.width ?? 0)
            let metalHeight = Int(metalView?.bounds.height ?? 0)
            streamLog("[StreamView] RendererContainerView first layout bounds=\(Int(bounds.width))x\(Int(bounds.height)) metalView=\(metalWidth)x\(metalHeight)")
        }
    }
}
#endif

