//
//  MetalVideoRenderer.swift
//  Northstar
//
//  RTCVideoRenderer that presents decoded NV12 frames through a CAMetalLayer on a dedicated
//  render thread, optionally upscaling to the display's native resolution with MetalFX spatial
//  scaling. Nothing on the per-frame path touches the main thread.
//
//  Pipeline (per presented frame, on the render thread):
//    WebRTC frame (RTCCVPixelBuffer NV12, IOSurface-backed)
//      ↓ CVMetalTextureCacheCreateTextureFromImage (zero-copy Y / CbCr textures)
//      ↓ metalfx rung:      nv12ToBGRA compute → MTLFXSpatialScaler → drawable (direct output)
//        passthrough rung:  nv12Passthrough render pass → drawable (bilinear, source-sized drawable)
//      ↓ present
//
//  Pacing:
//    .smooth      — CAMetalDisplayLink drives presentation; exactly one frame is presented per
//                   display refresh from a short queue, so bursts become consecutive frames instead
//                   of drops and there is never more than one drawable in flight.
//    .lowLatency  — frames are presented as soon as they arrive (latest wins); the display link is
//                   paused. Lower input latency, less even cadence on jittery links.
//

#if WEBRTC_AVAILABLE && canImport(UIKit) && canImport(Metal)
import UIKit
import Metal
import QuartzCore
#if canImport(MetalFX)
import MetalFX
#endif
import CoreVideo
import AVFoundation
import VideoRenderingKit

// MARK: - MetalVideoRenderer

/// Metal presentation path for the stream.
///
/// Thread-safety contract (the reason this is `@unchecked Sendable`):
/// - `lock` guards everything shared between the WebRTC decode thread, the main actor and the
///   render thread: the frame queue, the current `RenderRequest`, counters and telemetry sums.
/// - All Metal resources, the MetalFX scaler, the display link and the sizes they were built for
///   are owned by the render thread and only touched from `renderThread` (see `performOnRenderThread`).
/// - `layerView` is a UIKit object owned by the main actor; the render thread only uses its
///   `CAMetalLayer` through the display link, `nextDrawable()` and `drawableSize` (inside a
///   `CATransaction`).
/// - Callback closures are set once by the coordinator before the renderer is attached to a track
///   and are only invoked from the render thread.
final class MetalVideoRenderer: NSObject, RTCVideoRenderer, @unchecked Sendable {

    // MARK: - Public interface

    /// The UIKit view hosting the Metal layer. Add as a subview in the video container (main actor).
    let layerView: MetalVideoLayerView
    var metalDevice: MTLDevice { device }

    /// Called at most once per second with renderer counter telemetry.
    var onTelemetry: (@Sendable (TelemetrySnapshot) -> Void)?
    var onCandidateReady: (@Sendable (RenderLadderRung) -> Void)?
    var onCandidateFailed: (@Sendable (RenderLadderRung, String) -> Void)?
    /// Fired once per source-dimension change (not per frame).
    var onSourceDimensionsChanged: (@Sendable (Int, Int) -> Void)?
    var onFirstFrameDrawn: (@Sendable () -> Void)?

    /// How presentation is timed relative to frame arrival.
    enum PresentationPacing: Sendable, Equatable {
        case smooth
        case lowLatency
    }

    /// What the coordinator wants the renderer to do; applied by the render thread.
    struct RenderRequest: Equatable, Sendable {
        /// Active rung, or `nil` while the renderer is not the selected output.
        var rung: RenderLadderRung?
        /// Aspect-fitted processing target in display pixels (from the ladder plan).
        var targetWidth: Int
        var targetHeight: Int
        var pacing: PresentationPacing

        static let idle = RenderRequest(rung: nil, targetWidth: 0, targetHeight: 0, pacing: .smooth)
    }

    // MARK: - Shared renderer resources (render-thread owned unless noted)

    let device: MTLDevice
    let commandQueue: MTLCommandQueue
    let conversionPipelineState: MTLComputePipelineState
    let passthroughPipelineState: MTLRenderPipelineState
    var textureCache: CVMetalTextureCache

    /// Intermediate BGRA texture written by the compute kernel (source resolution).
    var outputTexture: MTLTexture?
    var outputSize: MTLSize = MTLSize(width: 0, height: 0, depth: 1)
#if canImport(MetalFX)
    var spatialScaler: (any MTLFXSpatialScaler)?
    /// Only used when the drawable cannot be the scaler's output texture.
    var spatialScalerFallbackTexture: MTLTexture?
    var spatialScalerInputSize: MTLSize = MTLSize(width: 0, height: 0, depth: 1)
    var spatialScalerOutputSize: MTLSize = MTLSize(width: 0, height: 0, depth: 1)
    /// Identity of the in-flight background scaler build, so stale results are discarded.
    var pendingScalerBuildID: UInt64 = 0
    var didLogDirectDrawableOutput = false
#endif
    var appliedRequest: RenderRequest = .idle
    var appliedDrawableSize = CGSize.zero
    var lastReadyRung: RenderLadderRung?
    var lastFailedRung: RenderLadderRung?
    var lastPresentedSequence: UInt64 = 0
    var didReportFirstDraw = false
    var lastTelemetryEmitTime: CFTimeInterval = CACurrentMediaTime()
    var displayLink: CAMetalDisplayLink?
    var displayLinkIsPaused = true

    // MARK: - Cross-thread state (guarded by `lock`)

    let lock = NSLock()
    /// Decoded frames waiting for presentation, oldest first. Bounded by `maxQueuedFrames`.
    var frameQueue: [PendingFrame] = []
    var request: RenderRequest = .idle
    var nextSequence: UInt64 = 1
    var lastSourceWidth = 0
    var lastSourceHeight = 0
    var framesReceived = 0
    var framesPresented = 0
    var framesDropped = 0
    var queueDepthMax = 0
    var gpuTimeAccumulatorMs: Double = 0
    var gpuTimeSampleCount = 0
    var presentLatencyAccumulatorMs: Double = 0
    var presentLatencySampleCount = 0
    var processingStatus: String?
    var processingInputWidth: Int?
    var processingInputHeight: Int?
    var processingOutputWidth: Int?
    var processingOutputHeight: Int?
    var lastError: String?
    var unsupportedPixelFormatReported = false

    /// Frames a burst may hold in `.smooth` pacing before the oldest is dropped. Two frames bound
    /// the added latency to one display interval while still turning a 2-frame burst into two
    /// consecutive presentations instead of a drop.
    static let maxQueuedFrames = 2

    struct PendingFrame {
        let pixelBuffer: CVPixelBuffer
        let arrivalTime: CFTimeInterval
        let sequence: UInt64
    }

    // MARK: - Render thread

    private let renderThread: Thread
    private let renderThreadReady = DispatchSemaphore(value: 0)

    /// Returns the latest renderer counters and processing state for diagnostics surfaces.
    var telemetrySnapshot: TelemetrySnapshot {
        lock.lock()
        defer { lock.unlock() }
        return makeTelemetrySnapshotLocked()
    }

    // MARK: - Init

    /// Returns nil if Metal is unavailable (simulator without Metal, unsupported hardware).
    /// Must be called on the main actor because the layer view is a UIView.
    @MainActor
    init?(frame: CGRect) {
        guard
            let device = MTLCreateSystemDefaultDevice(),
            let commandQueue = device.makeCommandQueue()
        else {
            streamLog("[MetalRenderer] Metal device/command queue unavailable — renderer init failed", force: true)
            return nil
        }
        self.device = device
        self.commandQueue = commandQueue
        commandQueue.label = "com.northstar.video.render"

        guard
            let library = device.makeDefaultLibrary(),
            let conversionFunction = library.makeFunction(name: "nv12ToBGRA"),
            let passthroughVertex = library.makeFunction(name: "nv12PassthroughVertex"),
            let passthroughFragment = library.makeFunction(name: "nv12PassthroughFragment")
        else {
            streamLog("[MetalRenderer] video shaders missing from default Metal library — renderer init failed", force: true)
            return nil
        }
        do {
            self.conversionPipelineState = try device.makeComputePipelineState(function: conversionFunction)
            let renderDescriptor = MTLRenderPipelineDescriptor()
            renderDescriptor.label = "nv12Passthrough"
            renderDescriptor.vertexFunction = passthroughVertex
            renderDescriptor.fragmentFunction = passthroughFragment
            renderDescriptor.colorAttachments[0].pixelFormat = .bgra8Unorm
            self.passthroughPipelineState = try device.makeRenderPipelineState(descriptor: renderDescriptor)
        } catch {
            streamLog("[MetalRenderer] pipeline state creation failed: \(error) — renderer init failed", force: true)
            return nil
        }

        var cache: CVMetalTextureCache?
        let cacheStatus = CVMetalTextureCacheCreate(kCFAllocatorDefault, nil, device, nil, &cache)
        guard cacheStatus == kCVReturnSuccess, let cache else {
            streamLog("[MetalRenderer] CVMetalTextureCacheCreate failed: \(cacheStatus)", force: true)
            return nil
        }
        self.textureCache = cache

        let view = MetalVideoLayerView(frame: frame)
        view.metalLayer.device = device
        self.layerView = view

        let thread = Thread()
        thread.name = "com.northstar.video.render"
        thread.qualityOfService = .userInteractive
        self.renderThread = thread

        super.init()

        let displayLink = CAMetalDisplayLink(metalLayer: view.metalLayer)
        displayLink.preferredFrameRateRange = CAFrameRateRange(minimum: 30, maximum: 60, preferred: 60)
        // One frame of render time between the callback and the target presentation keeps latency
        // low; the whole frame costs a few milliseconds of GPU time.
        displayLink.preferredFrameLatency = 1
        displayLink.delegate = self
        displayLink.isPaused = true
        self.displayLink = displayLink

        renderThread.main = { [weak self] in
            autoreleasepool {
                self?.renderThreadMain()
            }
        }
        renderThread.start()
        renderThreadReady.wait()
        streamLog("[MetalRenderer] MetalVideoRenderer initialised (device: \(device.name))", force: true)
    }

    deinit {
        displayLink?.invalidate()
        renderThread.cancel()
    }

    // MARK: - RTCVideoRenderer

    /// WebRTC size hint; the pipeline sizes itself from each pixel buffer, so nothing to do here.
    func setSize(_ size: CGSize) {}

    /// Called on a WebRTC background thread for every decoded frame.
    func renderFrame(_ frame: RTCVideoFrame?) {
        guard let frame else { return }
        guard let pixelBuffer = (frame.buffer as? RTCCVPixelBuffer)?.pixelBuffer else {
            return
        }

        let width = CVPixelBufferGetWidth(pixelBuffer)
        let height = CVPixelBufferGetHeight(pixelBuffer)
        let arrivalTime = CACurrentMediaTime()

        lock.lock()
        framesReceived += 1
        let dimensionsChanged = width != lastSourceWidth || height != lastSourceHeight
        if dimensionsChanged {
            lastSourceWidth = width
            lastSourceHeight = height
        }
        let currentRequest = request
        let sequence = nextSequence
        nextSequence &+= 1
        let isSelected = currentRequest.rung != nil
        var kickImmediate = false
        if isSelected {
            let pending = PendingFrame(pixelBuffer: pixelBuffer, arrivalTime: arrivalTime, sequence: sequence)
            switch currentRequest.pacing {
            case .smooth:
                frameQueue.append(pending)
                if frameQueue.count > Self.maxQueuedFrames {
                    frameQueue.removeFirst(frameQueue.count - Self.maxQueuedFrames)
                    framesDropped += 1
                }
            case .lowLatency:
                if !frameQueue.isEmpty {
                    framesDropped += frameQueue.count
                }
                frameQueue = [pending]
                kickImmediate = true
            }
            queueDepthMax = max(queueDepthMax, frameQueue.count)
        }
        lock.unlock()

        if dimensionsChanged {
            onSourceDimensionsChanged?(width, height)
        }
        if kickImmediate {
            performOnRenderThread { [weak self] in
                self?.presentImmediatelyIfNeeded()
            }
        }
    }

    // MARK: - Requests from the coordinator (main actor)

    /// Records what the coordinator wants and lets the render thread apply it.
    func setRequest(_ newRequest: RenderRequest) {
        lock.lock()
        let changed = request != newRequest
        request = newRequest
        if changed {
            if newRequest.rung != appliedRequestRungForResetLocked() {
                lastError = nil
            }
            if newRequest.rung == nil {
                frameQueue.removeAll()
            }
            processingStatus = newRequest.rung?.rawName
        }
        lock.unlock()
        guard changed else { return }
        performOnRenderThread { [weak self] in
            self?.applyPendingRequest()
        }
    }

    /// Reads the rung most recently applied on the render thread without touching render-thread state.
    private func appliedRequestRungForResetLocked() -> RenderLadderRung? {
        // `appliedRequest` is render-thread owned; the comparison here only decides whether to clear
        // the diagnostic error string, so a stale read is harmless.
        appliedRequest.rung
    }

    // MARK: - Render thread plumbing

    private func renderThreadMain() {
        let runLoop = RunLoop.current
        // Keep the run loop alive even when no display link or job is scheduled.
        runLoop.add(Port(), forMode: .default)
        displayLink?.add(to: runLoop, forMode: .default)
        renderThreadReady.signal()
        while !Thread.current.isCancelled {
            autoreleasepool {
                _ = runLoop.run(mode: .default, before: .distantFuture)
            }
        }
    }

    private final class RenderJob: NSObject {
        let body: () -> Void
        init(body: @escaping () -> Void) {
            self.body = body
        }
    }

    /// Runs `body` on the render thread's run loop (asynchronously, in order).
    func performOnRenderThread(_ body: @escaping () -> Void) {
        if Thread.current === renderThread {
            body()
            return
        }
        perform(
            #selector(runRenderJob(_:)),
            on: renderThread,
            with: RenderJob(body: body),
            waitUntilDone: false,
            modes: [RunLoop.Mode.default.rawValue]
        )
    }

    @objc private func runRenderJob(_ job: Any) {
        guard let job = job as? RenderJob else { return }
        job.body()
    }
}

// MARK: - Telemetry

extension MetalVideoRenderer {
    struct TelemetrySnapshot: Sendable {
        let framesReceived: Int
        let framesPresented: Int
        let framesDropped: Int
        let queueDepthMax: Int
        let processingStatus: String?
        let processingInputWidth: Int?
        let processingInputHeight: Int?
        let processingOutputWidth: Int?
        let processingOutputHeight: Int?
        /// Average arrival → on-glass latency over the last telemetry window.
        let renderLatencyMs: Double?
        /// Average GPU time per presented frame over the last telemetry window.
        let gpuFrameTimeMs: Double?
        let lastError: String?
    }

    /// Builds a snapshot from the current counters. Caller must hold `lock`.
    func makeTelemetrySnapshotLocked() -> TelemetrySnapshot {
        TelemetrySnapshot(
            framesReceived: framesReceived,
            framesPresented: framesPresented,
            framesDropped: framesDropped,
            queueDepthMax: queueDepthMax,
            processingStatus: processingStatus,
            processingInputWidth: processingInputWidth,
            processingInputHeight: processingInputHeight,
            processingOutputWidth: processingOutputWidth,
            processingOutputHeight: processingOutputHeight,
            renderLatencyMs: presentLatencySampleCount > 0
                ? presentLatencyAccumulatorMs / Double(presentLatencySampleCount)
                : nil,
            gpuFrameTimeMs: gpuTimeSampleCount > 0
                ? gpuTimeAccumulatorMs / Double(gpuTimeSampleCount)
                : nil,
            lastError: lastError
        )
    }

    /// Emits telemetry once per second and resets the per-window averages.
    func emitTelemetryIfNeeded(now: CFTimeInterval) {
        guard now - lastTelemetryEmitTime >= 1 else { return }
        lastTelemetryEmitTime = now
        lock.lock()
        let snapshot = makeTelemetrySnapshotLocked()
        gpuTimeAccumulatorMs = 0
        gpuTimeSampleCount = 0
        presentLatencyAccumulatorMs = 0
        presentLatencySampleCount = 0
        lock.unlock()
        onTelemetry?(snapshot)
    }
}

#endif // WEBRTC_AVAILABLE && canImport(UIKit) && canImport(Metal)

