// MetalVideoRendererDrawPipeline.swift
// Defines metal video renderer draw pipeline for the Integration / WebRTC surface.
//

#if WEBRTC_AVAILABLE && canImport(UIKit) && canImport(Metal)
import Foundation
import CoreVideo
import Metal
import QuartzCore
#if canImport(MetalFX)
import MetalFX
#endif
import VideoRenderingKit

// MARK: - Display link (smooth pacing)

extension MetalVideoRenderer: CAMetalDisplayLinkDelegate {
    /// Runs on the render thread once per display refresh; presents at most one queued frame.
    func metalDisplayLink(_ link: CAMetalDisplayLink, needsUpdate update: CAMetalDisplayLink.Update) {
        applyPendingRequest()
        guard let frame = dequeueOldestFrame() else {
            emitTelemetryIfNeeded(now: CACurrentMediaTime())
            return
        }
        render(frame, into: update.drawable)
    }

    private func dequeueOldestFrame() -> PendingFrame? {
        lock.lock()
        defer { lock.unlock() }
        guard request.rung != nil, !frameQueue.isEmpty else { return nil }
        return frameQueue.removeFirst()
    }
}

// MARK: - Immediate presentation (low-latency pacing)

extension MetalVideoRenderer {
    /// Presents the newest frame right away. Only used in `.lowLatency` pacing, on the render thread.
    func presentImmediatelyIfNeeded() {
        applyPendingRequest()
        lock.lock()
        let isImmediate = request.pacing == .lowLatency && request.rung != nil
        let frame = isImmediate ? frameQueue.popLast() : nil
        if isImmediate {
            frameQueue.removeAll()
        }
        lock.unlock()
        guard let frame else { return }
        // Blocks only on this thread, and only when both drawables are still queued for display.
        guard let drawable = layerView.metalLayer.nextDrawable() else {
            return
        }
        render(frame, into: drawable)
    }
}

// MARK: - Frame rendering

extension MetalVideoRenderer {
    /// Keeps the decoder buffer and its texture views alive until the GPU has consumed them.
    /// `@unchecked Sendable`: immutable after init; it only carries references across the
    /// command-buffer completion boundary.
    private final class InFlightFrame: @unchecked Sendable {
        let pixelBuffer: CVPixelBuffer
        let yTexture: CVMetalTexture
        let cbcrTexture: CVMetalTexture

        init(pixelBuffer: CVPixelBuffer, yTexture: CVMetalTexture, cbcrTexture: CVMetalTexture) {
            self.pixelBuffer = pixelBuffer
            self.yTexture = yTexture
            self.cbcrTexture = cbcrTexture
        }
    }

    /// Encodes and presents one frame into `drawable`. Render thread only.
    func render(_ frame: PendingFrame, into drawable: any CAMetalDrawable) {
        let now = CACurrentMediaTime()
        defer { emitTelemetryIfNeeded(now: now) }

        let pixelBuffer = frame.pixelBuffer
        let pixelFormat = CVPixelBufferGetPixelFormatType(pixelBuffer)
        let isFullRange: Bool
        switch pixelFormat {
        case kCVPixelFormatType_420YpCbCr8BiPlanarVideoRange:
            isFullRange = false
        case kCVPixelFormatType_420YpCbCr8BiPlanarFullRange:
            isFullRange = true
        default:
            reportUnsupportedPixelFormat(pixelFormat)
            return
        }

        let width = CVPixelBufferGetWidth(pixelBuffer)
        let height = CVPixelBufferGetHeight(pixelBuffer)
        guard width > 0, height > 0 else { return }
        prepareResources(sourceWidth: width, sourceHeight: height)

        var yRef: CVMetalTexture?
        CVMetalTextureCacheCreateTextureFromImage(
            kCFAllocatorDefault, textureCache, pixelBuffer, nil,
            .r8Unorm, width, height, 0, &yRef
        )
        var cbcrRef: CVMetalTexture?
        CVMetalTextureCacheCreateTextureFromImage(
            kCFAllocatorDefault, textureCache, pixelBuffer, nil,
            .rg8Unorm, width / 2, height / 2, 1, &cbcrRef
        )
        guard
            let yRef, let cbcrRef,
            let yTexture = CVMetalTextureGetTexture(yRef),
            let cbcrTexture = CVMetalTextureGetTexture(cbcrRef),
            let commandBuffer = commandQueue.makeCommandBuffer()
        else {
            recordError("Metal texture creation failed for \(width)x\(height)")
            return
        }
        commandBuffer.label = "video-frame"

        var fullRangeFlag: UInt32 = isFullRange ? 1 : 0
        let drawableTexture = drawable.texture
        let usedScaler: Bool
#if canImport(MetalFX)
        if let scaler = readySpatialScaler(
            sourceWidth: width,
            sourceHeight: height,
            drawableWidth: drawableTexture.width,
            drawableHeight: drawableTexture.height
        ), let outputTexture {
            encodeConversion(
                commandBuffer: commandBuffer,
                yTexture: yTexture,
                cbcrTexture: cbcrTexture,
                output: outputTexture,
                fullRangeFlag: &fullRangeFlag
            )
            encodeSpatialScale(
                scaler: scaler,
                commandBuffer: commandBuffer,
                input: outputTexture,
                drawableTexture: drawableTexture
            )
            usedScaler = true
        } else {
            usedScaler = false
        }
#else
        usedScaler = false
#endif
        if !usedScaler {
            encodePassthrough(
                commandBuffer: commandBuffer,
                yTexture: yTexture,
                cbcrTexture: cbcrTexture,
                drawableTexture: drawableTexture,
                fullRangeFlag: &fullRangeFlag
            )
        }

        let inFlight = InFlightFrame(pixelBuffer: pixelBuffer, yTexture: yRef, cbcrTexture: cbcrRef)
        commandBuffer.addCompletedHandler { [weak self] completed in
            withExtendedLifetime(inFlight) {}
            guard let self else { return }
            let gpuSeconds = completed.gpuEndTime - completed.gpuStartTime
            guard gpuSeconds > 0, gpuSeconds.isFinite else { return }
            self.lock.lock()
            self.gpuTimeAccumulatorMs += gpuSeconds * 1_000
            self.gpuTimeSampleCount += 1
            self.lock.unlock()
        }
        let arrivalTime = frame.arrivalTime
        drawable.addPresentedHandler { [weak self] presented in
            guard let self, presented.presentedTime > 0 else { return }
            let latencyMs = (presented.presentedTime - arrivalTime) * 1_000
            self.lock.lock()
            self.presentLatencyAccumulatorMs += latencyMs
            self.presentLatencySampleCount += 1
            self.lock.unlock()
        }
        commandBuffer.present(drawable)
        commandBuffer.commit()

        lock.lock()
        framesPresented += 1
        lastPresentedSequence = frame.sequence
        processingInputWidth = width
        processingInputHeight = height
        processingOutputWidth = usedScaler ? drawableTexture.width : width
        processingOutputHeight = usedScaler ? drawableTexture.height : height
        let shouldReportFirstDraw = !didReportFirstDraw
        didReportFirstDraw = true
        lock.unlock()

        if shouldReportFirstDraw {
            onFirstFrameDrawn?()
        }
    }

    private func encodeConversion(
        commandBuffer: any MTLCommandBuffer,
        yTexture: any MTLTexture,
        cbcrTexture: any MTLTexture,
        output: any MTLTexture,
        fullRangeFlag: inout UInt32
    ) {
        guard let encoder = commandBuffer.makeComputeCommandEncoder() else { return }
        encoder.label = "nv12ToBGRA"
        encoder.setComputePipelineState(conversionPipelineState)
        encoder.setTexture(yTexture, index: 0)
        encoder.setTexture(cbcrTexture, index: 1)
        encoder.setTexture(output, index: 2)
        encoder.setBytes(&fullRangeFlag, length: MemoryLayout<UInt32>.size, index: 2)
        let threadgroup = MTLSize(width: 16, height: 16, depth: 1)
        encoder.dispatchThreads(
            MTLSize(width: output.width, height: output.height, depth: 1),
            threadsPerThreadgroup: threadgroup
        )
        encoder.endEncoding()
    }

    private func encodePassthrough(
        commandBuffer: any MTLCommandBuffer,
        yTexture: any MTLTexture,
        cbcrTexture: any MTLTexture,
        drawableTexture: any MTLTexture,
        fullRangeFlag: inout UInt32
    ) {
        let passDescriptor = MTLRenderPassDescriptor()
        passDescriptor.colorAttachments[0].texture = drawableTexture
        passDescriptor.colorAttachments[0].loadAction = .dontCare
        passDescriptor.colorAttachments[0].storeAction = .store
        guard let encoder = commandBuffer.makeRenderCommandEncoder(descriptor: passDescriptor) else { return }
        encoder.label = "nv12Passthrough"
        encoder.setRenderPipelineState(passthroughPipelineState)
        encoder.setFragmentTexture(yTexture, index: 0)
        encoder.setFragmentTexture(cbcrTexture, index: 1)
        encoder.setFragmentBytes(&fullRangeFlag, length: MemoryLayout<UInt32>.size, index: 2)
        encoder.drawPrimitives(type: .triangle, vertexStart: 0, vertexCount: 3)
        encoder.endEncoding()
    }

#if canImport(MetalFX)
    private func encodeSpatialScale(
        scaler: any MTLFXSpatialScaler,
        commandBuffer: any MTLCommandBuffer,
        input: any MTLTexture,
        drawableTexture: any MTLTexture
    ) {
        scaler.colorTexture = input
        if drawableTexture.usage.isSuperset(of: scaler.outputTextureUsage) {
            if !didLogDirectDrawableOutput {
                didLogDirectDrawableOutput = true
                streamLog("[MetalRenderer] MetalFX writes directly into the drawable", force: true)
            }
            scaler.outputTexture = drawableTexture
            scaler.encode(commandBuffer: commandBuffer)
            return
        }

        // The drawable cannot be the scaler output on this configuration; go through an
        // intermediate and copy. Costs one extra full-resolution copy per frame.
        if spatialScalerFallbackTexture == nil
            || spatialScalerFallbackTexture?.width != drawableTexture.width
            || spatialScalerFallbackTexture?.height != drawableTexture.height {
            let descriptor = MTLTextureDescriptor.texture2DDescriptor(
                pixelFormat: .bgra8Unorm,
                width: drawableTexture.width,
                height: drawableTexture.height,
                mipmapped: false
            )
            descriptor.storageMode = .private
            descriptor.usage = scaler.outputTextureUsage.union(.shaderRead)
            spatialScalerFallbackTexture = device.makeTexture(descriptor: descriptor)
            if !didLogDirectDrawableOutput {
                didLogDirectDrawableOutput = true
                streamLog("[MetalRenderer] drawable usage \(drawableTexture.usage.rawValue) lacks scaler output usage \(scaler.outputTextureUsage.rawValue); using intermediate + blit", force: true)
            }
        }
        guard let intermediate = spatialScalerFallbackTexture else { return }
        scaler.outputTexture = intermediate
        scaler.encode(commandBuffer: commandBuffer)
        guard let blit = commandBuffer.makeBlitCommandEncoder() else { return }
        blit.copy(from: intermediate, to: drawableTexture)
        blit.endEncoding()
    }
#endif

    private func reportUnsupportedPixelFormat(_ pixelFormat: OSType) {
        lock.lock()
        let alreadyReported = unsupportedPixelFormatReported
        unsupportedPixelFormatReported = true
        let rung = request.rung
        lock.unlock()
        guard !alreadyReported, let rung else { return }
        notifyCandidateFailedIfNeeded(rung, reason: "unsupported pixel format \(pixelFormat) (Metal path handles 8-bit NV12 only)")
    }

    func recordError(_ message: String) {
        lock.lock()
        lastError = message
        lock.unlock()
    }
}
#endif

// MetalVideoRendererPresentationResources.swift
// Defines metal video renderer presentation resources for the Integration / WebRTC surface.
//

#if WEBRTC_AVAILABLE && canImport(UIKit) && canImport(Metal)
import Foundation
import CoreVideo
import Metal
import QuartzCore
#if canImport(MetalFX)
import MetalFX
#endif
import VideoRenderingKit

// Everything in this file runs on the render thread unless stated otherwise.
extension MetalVideoRenderer {

    // MARK: - Request application

    /// Applies the coordinator's latest request: pacing, rung and target.
    func applyPendingRequest() {
        lock.lock()
        let desired = request
        let sourceWidth = lastSourceWidth
        let sourceHeight = lastSourceHeight
        lock.unlock()
        guard desired != appliedRequest else { return }

        let previous = appliedRequest
        appliedRequest = desired

        setDisplayLinkPaused(desired.rung == nil || desired.pacing != .smooth)

        guard let rung = desired.rung else {
            // Deselected: drop the scaler so a later selection rebuilds for the then-current sizes.
            releaseSpatialScaler()
            lastReadyRung = nil
            lastFailedRung = nil
            return
        }

        if rung != previous.rung
            || desired.targetWidth != previous.targetWidth
            || desired.targetHeight != previous.targetHeight {
            lastReadyRung = nil
            lastFailedRung = nil
            lock.lock()
            unsupportedPixelFormatReported = false
            lock.unlock()
        }

        if sourceWidth > 0, sourceHeight > 0 {
            prepareResources(sourceWidth: sourceWidth, sourceHeight: sourceHeight)
        }
    }

    private func setDisplayLinkPaused(_ paused: Bool) {
        guard displayLinkIsPaused != paused, let displayLink else { return }
        displayLinkIsPaused = paused
        displayLink.isPaused = paused
    }

    // MARK: - Per-source-size resources

    /// Makes sure textures, scaler and drawable size match the current rung and source size.
    /// Cheap when nothing changed; called before every frame.
    func prepareResources(sourceWidth: Int, sourceHeight: Int) {
        guard let rung = appliedRequest.rung else { return }
        switch rung {
        case .passthrough:
            releaseSpatialScaler()
            outputTexture = nil
            outputSize = MTLSize(width: 0, height: 0, depth: 1)
            setDrawableSize(CGSize(width: sourceWidth, height: sourceHeight))
            notifyCandidateReadyIfNeeded(.passthrough)

        case .metalFXSpatial:
            let fitted = fittedTarget(sourceWidth: sourceWidth, sourceHeight: sourceHeight)
            guard fitted.width > sourceWidth || fitted.height > sourceHeight else {
                // Nothing to upscale for this source; present it 1:1 through the passthrough pass.
                releaseSpatialScaler()
                setDrawableSize(CGSize(width: sourceWidth, height: sourceHeight))
                notifyCandidateReadyIfNeeded(.metalFXSpatial)
                return
            }
            ensureOutputTexture(width: sourceWidth, height: sourceHeight)
            setDrawableSize(CGSize(width: fitted.width, height: fitted.height))
#if canImport(MetalFX)
            ensureSpatialScaler(
                inputWidth: sourceWidth,
                inputHeight: sourceHeight,
                outputWidth: fitted.width,
                outputHeight: fitted.height
            )
#else
            notifyCandidateFailedIfNeeded(.metalFXSpatial, reason: "MetalFX framework unavailable in this build")
#endif

        case .sampleBuffer, .vtSuperResolution:
            break
        }
    }

    /// Aspect-fits the source into the requested processing target; never downsizes.
    private func fittedTarget(sourceWidth: Int, sourceHeight: Int) -> (width: Int, height: Int) {
        let targetWidth = appliedRequest.targetWidth
        let targetHeight = appliedRequest.targetHeight
        guard targetWidth > 0, targetHeight > 0 else {
            return (sourceWidth, sourceHeight)
        }
        let scale = min(Double(targetWidth) / Double(sourceWidth), Double(targetHeight) / Double(sourceHeight))
        guard scale.isFinite, scale > 1 else {
            return (sourceWidth, sourceHeight)
        }
        // Even dimensions keep the scaler and drawable happy with 4:2:0-derived content.
        let width = max(sourceWidth, Int((Double(sourceWidth) * scale).rounded(.down)) & ~1)
        let height = max(sourceHeight, Int((Double(sourceHeight) * scale).rounded(.down)) & ~1)
        return (width, height)
    }

    private func ensureOutputTexture(width: Int, height: Int) {
        if let outputTexture, outputTexture.width == width, outputTexture.height == height {
            return
        }
        let descriptor = MTLTextureDescriptor.texture2DDescriptor(
            pixelFormat: .bgra8Unorm,
            width: width,
            height: height,
            mipmapped: false
        )
        descriptor.usage = [.shaderWrite, .shaderRead]
        descriptor.storageMode = .private
        outputTexture = device.makeTexture(descriptor: descriptor)
        outputTexture?.label = "nv12ToBGRA-output"
        outputSize = MTLSize(width: width, height: height, depth: 1)
        // Texture views for the previous size are no longer reachable; let the cache drop them.
        CVMetalTextureCacheFlush(textureCache, 0)
    }

    /// Sets the layer's drawable size when it actually changes. Reallocates the drawable pool,
    /// so it only happens on rung or source-size changes, never per frame.
    private func setDrawableSize(_ size: CGSize) {
        guard size.width > 0, size.height > 0, size != appliedDrawableSize else { return }
        appliedDrawableSize = size
        CATransaction.begin()
        CATransaction.setDisableActions(true)
        layerView.metalLayer.drawableSize = size
        CATransaction.commit()
    }

    // MARK: - MetalFX spatial scaler

#if canImport(MetalFX)
    /// Returns the scaler when it matches the current source and drawable sizes, else nil.
    func readySpatialScaler(
        sourceWidth: Int,
        sourceHeight: Int,
        drawableWidth: Int,
        drawableHeight: Int
    ) -> (any MTLFXSpatialScaler)? {
        guard appliedRequest.rung == .metalFXSpatial, let spatialScaler else { return nil }
        guard spatialScalerInputSize.width == sourceWidth,
              spatialScalerInputSize.height == sourceHeight,
              spatialScalerOutputSize.width == drawableWidth,
              spatialScalerOutputSize.height == drawableHeight
        else {
            return nil
        }
        return spatialScaler
    }

    /// Owns a freshly built scaler while it crosses from the build queue to the render thread.
    /// `@unchecked Sendable`: the box is created on the build queue and consumed exactly once on
    /// the render thread; nothing else references the scaler in between.
    private final class ScalerHandoff: @unchecked Sendable {
        let scaler: (any MTLFXSpatialScaler)?
        init(scaler: (any MTLFXSpatialScaler)?) {
            self.scaler = scaler
        }
    }

    /// Builds the scaler off the render thread when sizes change. Frames keep flowing through the
    /// passthrough pass until the new scaler lands; MetalFX scaler creation compiles pipelines and
    /// can take longer than a frame.
    private func ensureSpatialScaler(inputWidth: Int, inputHeight: Int, outputWidth: Int, outputHeight: Int) {
        if spatialScaler != nil,
           spatialScalerInputSize.width == inputWidth,
           spatialScalerInputSize.height == inputHeight,
           spatialScalerOutputSize.width == outputWidth,
           spatialScalerOutputSize.height == outputHeight {
            notifyCandidateReadyIfNeeded(.metalFXSpatial)
            return
        }
        if pendingScalerBuildSizes == (inputWidth, inputHeight, outputWidth, outputHeight) {
            return
        }

        pendingScalerBuildID &+= 1
        pendingScalerBuildSizes = (inputWidth, inputHeight, outputWidth, outputHeight)
        let buildID = pendingScalerBuildID
        let device = self.device
        let startTime = CACurrentMediaTime()
        DispatchQueue.global(qos: .userInitiated).async { [weak self] in
            let descriptor = MTLFXSpatialScalerDescriptor()
            descriptor.inputWidth = inputWidth
            descriptor.inputHeight = inputHeight
            descriptor.outputWidth = outputWidth
            descriptor.outputHeight = outputHeight
            descriptor.colorTextureFormat = .bgra8Unorm
            descriptor.outputTextureFormat = .bgra8Unorm
            descriptor.colorProcessingMode = .perceptual
            let handoff = ScalerHandoff(scaler: descriptor.makeSpatialScaler(device: device))
            let buildMs = (CACurrentMediaTime() - startTime) * 1_000
            self?.performOnRenderThread { [weak self] in
                self?.installSpatialScaler(
                    handoff.scaler,
                    buildID: buildID,
                    inputWidth: inputWidth,
                    inputHeight: inputHeight,
                    outputWidth: outputWidth,
                    outputHeight: outputHeight,
                    buildMs: buildMs
                )
            }
        }
    }

    private func installSpatialScaler(
        _ scaler: (any MTLFXSpatialScaler)?,
        buildID: UInt64,
        inputWidth: Int,
        inputHeight: Int,
        outputWidth: Int,
        outputHeight: Int,
        buildMs: Double
    ) {
        guard buildID == pendingScalerBuildID else { return } // superseded by a newer build
        pendingScalerBuildSizes = nil
        guard appliedRequest.rung == .metalFXSpatial else { return }

        guard let scaler else {
            releaseSpatialScaler()
            notifyCandidateFailedIfNeeded(
                .metalFXSpatial,
                reason: "MetalFX spatial scaler unavailable for \(inputWidth)x\(inputHeight) -> \(outputWidth)x\(outputHeight)"
            )
            return
        }

        if let outputTexture, !outputTexture.usage.isSuperset(of: scaler.colorTextureUsage) {
            let descriptor = MTLTextureDescriptor.texture2DDescriptor(
                pixelFormat: .bgra8Unorm,
                width: outputTexture.width,
                height: outputTexture.height,
                mipmapped: false
            )
            descriptor.usage = outputTexture.usage.union(scaler.colorTextureUsage)
            descriptor.storageMode = .private
            self.outputTexture = device.makeTexture(descriptor: descriptor)
        }

        spatialScaler = scaler
        spatialScalerInputSize = MTLSize(width: inputWidth, height: inputHeight, depth: 1)
        spatialScalerOutputSize = MTLSize(width: outputWidth, height: outputHeight, depth: 1)
        spatialScalerFallbackTexture = nil
        streamLog(
            "[MetalRenderer] MetalFX spatial scaler ready \(inputWidth)x\(inputHeight) -> \(outputWidth)x\(outputHeight) (built in \(Int(buildMs)) ms)",
            force: true
        )
        notifyCandidateReadyIfNeeded(.metalFXSpatial)
    }

    private func releaseSpatialScaler() {
        pendingScalerBuildID &+= 1
        pendingScalerBuildSizes = nil
        spatialScaler = nil
        spatialScalerFallbackTexture = nil
        spatialScalerInputSize = MTLSize(width: 0, height: 0, depth: 1)
        spatialScalerOutputSize = MTLSize(width: 0, height: 0, depth: 1)
    }
#else
    private func releaseSpatialScaler() {}
#endif

    // MARK: - Ladder notifications

    func notifyCandidateReadyIfNeeded(_ rung: RenderLadderRung) {
        guard lastReadyRung != rung else { return }
        lastReadyRung = rung
        lastFailedRung = nil
        lock.lock()
        processingStatus = rung.rawName
        lock.unlock()
        onCandidateReady?(rung)
    }

    func notifyCandidateFailedIfNeeded(_ rung: RenderLadderRung, reason: String) {
        guard lastFailedRung != rung else { return }
        lastFailedRung = rung
        lock.lock()
        processingStatus = "failed"
        lastError = reason
        lock.unlock()
        onCandidateFailed?(rung, reason)
    }
}
#endif

// RendererAttachmentCoordinator.swift
// Defines the renderer attachment coordinator for the Features / Streaming surface.
//

import Foundation
import NorthstarCore
import NorthstarModels
import StreamingCore
import VideoRenderingKit
#if canImport(AVFoundation)
@preconcurrency import AVFoundation
@preconcurrency import CoreMedia
#endif
#if canImport(AVKit)
import AVKit
#endif
#if canImport(UIKit)
import UIKit
#endif
#if canImport(Metal)
import Metal
#endif

#if WEBRTC_AVAILABLE && canImport(UIKit)
@MainActor
/// Owns the concrete renderer attachment lifecycle for a stream session's UIKit surface.
///
/// Policy lives here: which rung is active, when to climb or fall back, how frames are paced,
/// and when thermal pressure forces the cheapest path. The renderers only execute requests.
final class RendererAttachmentCoordinator: NSObject {
    /// Callback hooks used to surface renderer mode, telemetry, and first-frame events.
    struct Callbacks {
        var onRendererModeChanged: @MainActor (String) -> Void
        var onRendererTelemetryChanged: @MainActor (StreamSurfaceModel.RendererTelemetrySnapshot) -> Void
        var onRendererDecodeFailure: @MainActor (String) -> Void
        var onFirstVideoFrameDrawn: @MainActor () -> Void

        static let noop = Callbacks(
            onRendererModeChanged: { _ in },
            onRendererTelemetryChanged: { _ in },
            onRendererDecodeFailure: { _ in },
            onFirstVideoFrameDrawn: {}
        )
    }

    /// Configuration bundle derived from live settings and passed into the renderer pipeline.
    struct Configuration {
        var upscalingEnabled: Bool
        var frameProbeEnabled: Bool
        var hdrEnabled: Bool
        var lowLatencyMode: Bool
        var floorBehavior: RenderLadderFloorBehavior
        var preferredUpscaler: UpscalerPreference
        var callbacks: Callbacks

        /// Creates a configuration snapshot from the current settings store values.
        @MainActor
        static func make(
            settingsStore: SettingsStore,
            callbacks: Callbacks
        ) -> Self {
            let floorBehavior: RenderLadderFloorBehavior
            switch settingsStore.diagnostics.upscalingFloorBehavior {
            case .metalFloor:
                floorBehavior = .metalFloor
            case .sampleFloor:
                floorBehavior = .sampleFloor
            }
            let preferredUpscaler: UpscalerPreference
            switch settingsStore.diagnostics.preferredUpscaler {
            case .automatic:
                preferredUpscaler = .automatic
            case .metalFX:
                preferredUpscaler = .metalFXSpatial
            case .vtSuperResolution:
                preferredUpscaler = .vtSuperResolution
            }
            return Self(
                upscalingEnabled: settingsStore.stream.upscalingEnabled,
                frameProbeEnabled: settingsStore.diagnostics.frameProbe,
                hdrEnabled: settingsStore.stream.hdrEnabled,
                lowLatencyMode: settingsStore.stream.lowLatencyMode,
                floorBehavior: floorBehavior,
                preferredUpscaler: preferredUpscaler,
                callbacks: callbacks
            )
        }
    }

    /// Internal event stream used to serialize renderer callbacks back onto the main actor.
    private enum CallbackEvent: Sendable {
        case firstVideoFrameDrawn
        case decodeFailure(String)
        case sourceDimensionsChanged(width: Int, height: Int)
        case candidateReady(RenderLadderRung, outputFamily: String)
        case candidateFailed(RenderLadderRung, reason: String)
        case sampleTelemetry(StreamSurfaceModel.RendererTelemetrySnapshot)
        case metalTelemetry(StreamSurfaceModel.RendererTelemetrySnapshot)
    }

    /// Pump that forwards callback events into the coordinator's main-actor handlers.
    private final class CallbackEventPump {
        let continuation: AsyncStream<CallbackEvent>.Continuation
        private let task: Task<Void, Never>

        init(owner: RendererAttachmentCoordinator) {
            var capturedContinuation: AsyncStream<CallbackEvent>.Continuation?
            let stream = AsyncStream<CallbackEvent>(bufferingPolicy: .unbounded) {
                capturedContinuation = $0
            }
            self.continuation = capturedContinuation!
            self.task = Task { [weak owner] in
                for await event in stream {
                    guard let owner else { return }
                    await owner.handleCallbackEvent(event)
                }
            }
        }

        deinit {
            continuation.finish()
            task.cancel()
        }
    }

    private enum AttachedRenderer {
        case none
        case sampleBuffer
        case metal
    }

    /// The active container view hosting the sample-buffer and Metal renderers.
    weak var container: UIView?
    var metalRenderer: MetalVideoRenderer?
    weak var sampleBufferView: SampleBufferDisplayView?
    private var attachedTrack: RTCVideoTrack?
    private var attachedRenderer: AttachedRenderer = .none
    private let frameProbe = FrameProbeRenderer()
    private var frameProbeEnabled = false
    private var isFrameProbeAttached = false
    let sampleBufferRenderer = SampleBufferDisplayRenderer()
    private let ladderPlanner = RenderLadderPlanner(
        resolver: UpscaleCapabilityResolver(probe: LiveUpscaleCapabilityProbe())
    )
    private var callbacks: Callbacks = .noop
    private var sampleRendererSnapshot: StreamSurfaceModel.RendererTelemetrySnapshot = .cleared
    private var metalRendererSnapshot: StreamSurfaceModel.RendererTelemetrySnapshot = .cleared
    private var upscalingEnabled = true
    private var lowLatencyMode = false
    private var floorBehavior: RenderLadderFloorBehavior = .sampleFloor
    private var preferredUpscaler: UpscalerPreference = .automatic
    private var lastAppliedUpscalingEnabled: Bool?
    private var lastAppliedLowLatencyMode: Bool?
    private var lastAppliedFloorBehavior: RenderLadderFloorBehavior?
    private var lastAppliedPreferredUpscaler: UpscalerPreference?
    private var lastAppliedFrameProbeEnabled: Bool?
    private var lastAppliedContainerBounds: CGSize?
    private var lastRendererMode: String?
    private var lastRendererTelemetry: StreamSurfaceModel.RendererTelemetrySnapshot?
    private var hasReportedRendererDecodeFailure = false
    private var lastSourceDimensions: StreamDimensions?
    private var ladderPlan: RenderLadderPlan?
    private let maxCandidateFailureCount = 3
    private var candidateFailureCounts: [RenderLadderRung: Int] = [:]
    private var deadRungs: Set<RenderLadderRung> = []
    private var activeRung: RenderLadderRung = .sampleBuffer
    private var pendingRung: RenderLadderRung?
    private var outputFamily = "sampleBuffer"
    private var lastFallbackReason: String?
    private var thermalThrottled = false
    private var thermalObservation: Task<Void, Never>?
    private var didApplyDisplayCriteria = false
    private var didWireRendererCallbacks = false
    private lazy var callbackEventPump = CallbackEventPump(owner: self)

    /// Returns whether the optional frame-probe renderer should be attached.
    private var shouldAttachFrameProbe: Bool {
        frameProbeEnabled
    }

    private var pacing: MetalVideoRenderer.PresentationPacing {
        lowLatencyMode ? .lowLatency : .smooth
    }

    /// Installs or reuses the render container inside the provided host view.
    func install(
        in view: UIView,
        configuration: Configuration
    ) {
        let container: RendererContainerView
        if let existing = view as? RendererContainerView {
            container = existing
        } else {
            let newContainer = RendererContainerView(frame: view.bounds)
            newContainer.autoresizingMask = [.flexibleWidth, .flexibleHeight]
            view.addSubview(newContainer)
            container = newContainer
        }

        container.backgroundColor = .black
        container.isOpaque = true
        self.container = container

        if container.sampleBufferView == nil {
            let sampleBufferView = SampleBufferDisplayView(frame: .zero)
            sampleBufferView.translatesAutoresizingMaskIntoConstraints = true
            sampleBufferView.autoresizingMask = [.flexibleWidth, .flexibleHeight]
            sampleBufferView.frame = container.bounds
            sampleBufferView.backgroundColor = .clear
            sampleBufferView.displayLayer.videoGravity = .resizeAspect
            sampleBufferView.displayLayer.backgroundColor = UIColor.black.cgColor
            sampleBufferView.displayLayer.isOpaque = true
            sampleBufferView.isUserInteractionEnabled = false
            container.addSubview(sampleBufferView)
            container.sampleBufferView = sampleBufferView
            sampleBufferRenderer.bind(to: sampleBufferView)
        }

        if metalRenderer == nil, let renderer = MetalVideoRenderer(frame: container.bounds) {
            let metalView = renderer.layerView
            metalView.translatesAutoresizingMaskIntoConstraints = true
            metalView.autoresizingMask = [.flexibleWidth, .flexibleHeight]
            metalView.frame = container.bounds
            metalView.isHidden = true
            container.addSubview(metalView)
            container.metalView = metalView
            metalRenderer = renderer
        } else if metalRenderer == nil {
            streamLog("[StreamView] MetalVideoRenderer init failed — using sample-buffer floor only", force: true)
        }

        sampleBufferView = container.sampleBufferView
        wireRendererCallbacksIfNeeded()
        applyConfiguration(configuration)
        startThermalObservationIfNeeded()
        showOutputFamily("sampleBuffer")
        publishAggregatedRendererState()
        streamLog("[StreamView] makeUIView created video surface container")
    }

    /// Updates renderer state, bounds, and track attachment for an already-installed container.
    func update(
        in view: UIView,
        videoTrack rawTrack: AnyObject?,
        configuration: Configuration
    ) {
        guard let container = (view as? RendererContainerView) ?? self.container as? RendererContainerView else {
            return
        }
        self.container = container
        sampleBufferView = container.sampleBufferView
        applyConfiguration(configuration)

        let boundsChanged = lastAppliedContainerBounds != container.bounds.size
        if boundsChanged {
            metalRenderer?.layerView.frame = container.bounds
            if let sampleBufferView = container.sampleBufferView {
                sampleBufferView.frame = container.bounds
                sampleBufferRenderer.updateDisplayTarget(from: sampleBufferView)
            }
        }
        applyIfNeeded(videoTrack: rawTrack, containerBounds: container.bounds.size)
    }

    /// Tears down attached renderers and clears the cached session state.
    func clear() {
        detachRenderers()
        thermalObservation?.cancel()
        thermalObservation = nil
        clearDisplayCriteria()
        metalRenderer?.setRequest(.idle)
        if let metalRenderer {
            metalRenderer.onTelemetry = nil
            metalRenderer.onCandidateReady = nil
            metalRenderer.onCandidateFailed = nil
            metalRenderer.onSourceDimensionsChanged = nil
            metalRenderer.onFirstFrameDrawn = nil
        }
        sampleBufferRenderer.reset()
        sampleBufferRenderer.onDecodeFailure = nil
        sampleBufferRenderer.onTelemetry = nil
        sampleBufferRenderer.onSourceDimensionsChanged = nil
        sampleBufferRenderer.onCandidateReady = nil
        sampleBufferRenderer.onCandidateFailed = nil
        sampleBufferRenderer.onFirstFrameDrawn = nil
        didWireRendererCallbacks = false
        callbacks = .noop
        metalRenderer = nil
        attachedTrack = nil
        attachedRenderer = .none
        sampleRendererSnapshot = .cleared
        metalRendererSnapshot = .cleared
        candidateFailureCounts.removeAll()
        deadRungs.removeAll()
        pendingRung = nil
        activeRung = .sampleBuffer
        outputFamily = "sampleBuffer"
        lastFallbackReason = nil
        lastRendererMode = nil
        lastRendererTelemetry = nil
        hasReportedRendererDecodeFailure = false
        lastAppliedUpscalingEnabled = nil
        lastAppliedLowLatencyMode = nil
        lastAppliedFloorBehavior = nil
        lastAppliedPreferredUpscaler = nil
        lastAppliedFrameProbeEnabled = nil
        lastAppliedContainerBounds = nil
        lastSourceDimensions = nil
        ladderPlan = nil
        thermalThrottled = false
    }

    // MARK: - Configuration

    private func applyConfiguration(_ configuration: Configuration) {
        callbacks = configuration.callbacks
        upscalingEnabled = configuration.upscalingEnabled
        lowLatencyMode = configuration.lowLatencyMode
        floorBehavior = configuration.floorBehavior
        preferredUpscaler = configuration.preferredUpscaler
        setFrameProbeEnabled(configuration.frameProbeEnabled)
        sampleBufferRenderer.setHDREnabled(configuration.hdrEnabled)
    }

    /// Connects renderer callbacks to the event pump exactly once per install; the closures
    /// capture only the continuation, so settings updates never need to touch them.
    private func wireRendererCallbacksIfNeeded() {
        guard !didWireRendererCallbacks else { return }
        didWireRendererCallbacks = true
        let eventContinuation = callbackEventPump.continuation
        sampleBufferRenderer.onFirstFrameDrawn = {
            eventContinuation.yield(.firstVideoFrameDrawn)
        }
        sampleBufferRenderer.onDecodeFailure = { details in
            eventContinuation.yield(.decodeFailure(details))
        }
        sampleBufferRenderer.onSourceDimensionsChanged = { width, height in
            eventContinuation.yield(.sourceDimensionsChanged(width: width, height: height))
        }
        sampleBufferRenderer.onCandidateReady = { rung in
            eventContinuation.yield(.candidateReady(rung, outputFamily: "sampleBuffer"))
        }
        sampleBufferRenderer.onCandidateFailed = { rung, reason in
            eventContinuation.yield(.candidateFailed(rung, reason: reason))
        }
        sampleBufferRenderer.onTelemetry = { snapshot in
            eventContinuation.yield(.sampleTelemetry(Self.makeSampleTelemetrySnapshot(from: snapshot)))
        }
        metalRenderer?.onFirstFrameDrawn = {
            eventContinuation.yield(.firstVideoFrameDrawn)
        }
        metalRenderer?.onSourceDimensionsChanged = { width, height in
            eventContinuation.yield(.sourceDimensionsChanged(width: width, height: height))
        }
        metalRenderer?.onCandidateReady = { rung in
            eventContinuation.yield(.candidateReady(rung, outputFamily: "metal"))
        }
        metalRenderer?.onCandidateFailed = { rung, reason in
            eventContinuation.yield(.candidateFailed(rung, reason: reason))
        }
        metalRenderer?.onTelemetry = { snapshot in
            eventContinuation.yield(.metalTelemetry(Self.makeMetalTelemetrySnapshot(from: snapshot)))
        }
    }

    private func handleCallbackEvent(_ event: CallbackEvent) {
        switch event {
        case .firstVideoFrameDrawn:
            callbacks.onFirstVideoFrameDrawn()
        case .decodeFailure(let details):
            reportRendererDecodeFailureIfNeeded(details)
        case .sourceDimensionsChanged(let width, let height):
            sourceDimensionsDidChange(width: width, height: height)
        case .candidateReady(let rung, let outputFamily):
            handleCandidateReady(rung, outputFamily: outputFamily)
        case .candidateFailed(let rung, let reason):
            handleCandidateFailure(rung, reason: reason)
        case .sampleTelemetry(let snapshot):
            sampleRendererSnapshot = snapshot
            publishAggregatedRendererState()
        case .metalTelemetry(let snapshot):
            metalRendererSnapshot = snapshot
            publishAggregatedRendererState()
        }
    }

    private static func makeSampleTelemetrySnapshot(
        from snapshot: SampleBufferDisplayRenderer.TelemetrySnapshot
    ) -> StreamSurfaceModel.RendererTelemetrySnapshot {
        StreamSurfaceModel.RendererTelemetrySnapshot(
            framesReceived: snapshot.framesReceived,
            framesDrawn: snapshot.framesDrawn,
            framesDroppedByCoalescing: snapshot.framesDroppedByCoalescing,
            drawQueueDepthMax: snapshot.drawQueueDepthMax,
            framesFailed: snapshot.framesFailed,
            processingStatus: snapshot.processingStatus,
            processingInputWidth: snapshot.processingInputWidth,
            processingInputHeight: snapshot.processingInputHeight,
            processingOutputWidth: snapshot.processingOutputWidth,
            processingOutputHeight: snapshot.processingOutputHeight,
            renderLatencyMs: snapshot.renderLatencyMs,
            gpuFrameTimeMs: nil,
            outputFamily: "sampleBuffer",
            eligibleRungs: [],
            deadRungs: [],
            lastError: snapshot.lastError
        )
    }

    private static func makeMetalTelemetrySnapshot(
        from snapshot: MetalVideoRenderer.TelemetrySnapshot
    ) -> StreamSurfaceModel.RendererTelemetrySnapshot {
        StreamSurfaceModel.RendererTelemetrySnapshot(
            framesReceived: snapshot.framesReceived,
            framesDrawn: snapshot.framesPresented,
            framesDroppedByCoalescing: snapshot.framesDropped,
            drawQueueDepthMax: snapshot.queueDepthMax,
            framesFailed: nil,
            processingStatus: snapshot.processingStatus,
            processingInputWidth: snapshot.processingInputWidth,
            processingInputHeight: snapshot.processingInputHeight,
            processingOutputWidth: snapshot.processingOutputWidth,
            processingOutputHeight: snapshot.processingOutputHeight,
            renderLatencyMs: snapshot.renderLatencyMs,
            gpuFrameTimeMs: snapshot.gpuFrameTimeMs,
            outputFamily: "metal",
            eligibleRungs: [],
            deadRungs: [],
            lastError: snapshot.lastError
        )
    }

    private func setFrameProbeEnabled(_ enabled: Bool) {
        guard frameProbeEnabled != enabled else { return }
        frameProbeEnabled = enabled
        updateAttachedRendererFamily()
    }

    private func reportRendererModeIfChanged(_ mode: String) {
        guard lastRendererMode != mode else { return }
        lastRendererMode = mode
        callbacks.onRendererModeChanged(mode)
    }

    private func reportRendererTelemetryIfChanged(_ snapshot: StreamSurfaceModel.RendererTelemetrySnapshot) {
        guard lastRendererTelemetry != snapshot else { return }
        lastRendererTelemetry = snapshot
        callbacks.onRendererTelemetryChanged(snapshot)
    }

    private func reportRendererDecodeFailureIfNeeded(_ details: String) {
        guard !hasReportedRendererDecodeFailure else { return }
        hasReportedRendererDecodeFailure = true
        callbacks.onRendererDecodeFailure(details)
    }

    // MARK: - Ladder

    private func sourceDimensionsDidChange(width: Int, height: Int) {
        let dimensions = StreamDimensions(width: width, height: height)
        guard lastSourceDimensions != dimensions else { return }
        let isFirstDimensions = lastSourceDimensions == nil
        lastSourceDimensions = dimensions
        if isFirstDimensions {
            applyDisplayCriteriaIfNeeded(width: width, height: height)
        }
        refreshLadderPlan(reason: isFirstDimensions ? "first frame" : "source resolution changed")
    }

    private func handleCandidateReady(_ rung: RenderLadderRung, outputFamily: String) {
        guard pendingRung == rung || activeRung == rung else { return }
        pendingRung = nil
        activeRung = rung
        self.outputFamily = outputFamily
        lastFallbackReason = nil
        showOutputFamily(outputFamily)
        updateAttachedRendererFamily()
        publishAggregatedRendererState()
    }

    private func handleCandidateFailure(_ rung: RenderLadderRung, reason: String) {
        candidateFailureCounts = ladderPlanner.failureCountsAfterFailure(
            rung,
            existingFailureCounts: candidateFailureCounts
        )
        let failureCount = candidateFailureCounts[rung, default: 0]
        deadRungs = ladderPlanner.deadRungs(
            from: candidateFailureCounts,
            maxFailures: maxCandidateFailureCount
        )
        if pendingRung == rung {
            pendingRung = nil
        }
        if deadRungs.contains(rung) {
            lastFallbackReason = "\(reason) (failed \(failureCount)x; disabling \(rung.rawName) for this session)"
        } else {
            lastFallbackReason = "\(reason) (attempt \(failureCount)/\(maxCandidateFailureCount))"
        }
        if activeRung == rung {
            fallToSampleFloor()
        }
        if deadRungs.contains(rung) {
            let nextCandidate = ladderPlan.flatMap { ladderPlanner.nextCandidate(in: $0, deadRungs: deadRungs) }
            streamLog(
                "[StreamView] Render ladder disabling \(rung.rawName) after \(failureCount)x failures; " +
                (nextCandidate.map { "advancing to \($0.rawName)" } ?? "no higher rung remains, staying on \(outputFamily)"),
                force: true
            )
        }
        publishAggregatedRendererState()
        attemptNextCandidateIfNeeded()
    }

    private func fallToSampleFloor() {
        activeRung = .sampleBuffer
        pendingRung = nil
        outputFamily = "sampleBuffer"
        sampleBufferRenderer.setRequestedRung(.sampleBuffer)
        metalRenderer?.setRequest(.idle)
        showOutputFamily("sampleBuffer")
        updateAttachedRendererFamily()
    }

    private func publishAggregatedRendererState() {
        let baseSnapshot = outputFamily == "metal" ? metalRendererSnapshot : sampleRendererSnapshot
        let desiredTarget = ladderPlan?.desiredProcessingTarget
        let effectiveStatus: String? = {
            if thermalThrottled {
                return "thermal-floor"
            }
            if let pendingRung, activeRung == .sampleBuffer {
                return "\(pendingRung.rawName)-warming"
            }
            return baseSnapshot.processingStatus
        }()
        let snapshot = StreamSurfaceModel.RendererTelemetrySnapshot(
            framesReceived: baseSnapshot.framesReceived,
            framesDrawn: baseSnapshot.framesDrawn,
            framesDroppedByCoalescing: baseSnapshot.framesDroppedByCoalescing,
            drawQueueDepthMax: baseSnapshot.drawQueueDepthMax,
            framesFailed: baseSnapshot.framesFailed,
            processingStatus: effectiveStatus,
            processingInputWidth: baseSnapshot.processingInputWidth ?? lastSourceDimensions?.width,
            processingInputHeight: baseSnapshot.processingInputHeight ?? lastSourceDimensions?.height,
            processingOutputWidth: baseSnapshot.processingOutputWidth ?? outputWidthFallback(desiredTarget: desiredTarget),
            processingOutputHeight: baseSnapshot.processingOutputHeight ?? outputHeightFallback(desiredTarget: desiredTarget),
            renderLatencyMs: baseSnapshot.renderLatencyMs,
            gpuFrameTimeMs: baseSnapshot.gpuFrameTimeMs,
            outputFamily: outputFamily,
            eligibleRungs: ladderPlan?.eligibleRungs.map(\.rawName) ?? [],
            deadRungs: deadRungs.map(\.rawName).sorted(),
            lastError: baseSnapshot.lastError ?? lastFallbackReason
        )
        reportRendererModeIfChanged(activeRung.rawName)
        reportRendererTelemetryIfChanged(snapshot)
    }

    private func showOutputFamily(_ family: String) {
        sampleBufferView?.isHidden = family == "metal"
        metalRenderer?.layerView.isHidden = family != "metal"
    }

    /// Current display target in native pixels (screen size, falling back to the source).
    private func currentDisplayTarget(for source: StreamDimensions) -> StreamDimensions {
        if let sampleBufferView {
            let displayTarget = sampleBufferView.displayTargetDimensions
            if let width = displayTarget.width, let height = displayTarget.height {
                return StreamDimensions(width: width, height: height)
            }
        }
        return source
    }

    /// Rebuilds the ladder plan for the current source, keeping the active rung when it is
    /// still eligible so resolution changes never bounce the picture through the floor.
    private func refreshLadderPlan(reason: String) {
        guard let source = lastSourceDimensions else {
            publishAggregatedRendererState()
            return
        }

        let target = currentDisplayTarget(for: source)
        let metalDevice = metalRenderer?.metalDevice ?? MTLCreateSystemDefaultDevice()
        let nextPlan = ladderPlanner.makePlan(
            device: metalDevice,
            sourceW: source.width,
            sourceH: source.height,
            targetW: target.width,
            targetH: target.height,
            upscalingEnabled: upscalingEnabled && !thermalThrottled,
            floorBehavior: floorBehavior,
            preference: preferredUpscaler
        )
        let planChanged = ladderPlan != nextPlan
        ladderPlan = nextPlan
        guard planChanged else {
            publishAggregatedRendererState()
            return
        }

        // A new source size deserves a fresh retry budget; a rung that failed at one size can work at another.
        candidateFailureCounts.removeAll()
        deadRungs.removeAll()
        lastFallbackReason = nil
        logCurrentLadderPlan(reason: reason)

        let currentRung = pendingRung ?? activeRung
        if currentRung != .sampleBuffer, nextPlan.eligibleRungs.contains(currentRung) {
            // Keep the picture where it is; the renderer resizes its own resources.
            issueRequest(for: currentRung)
            publishAggregatedRendererState()
            return
        }

        if currentRung != .sampleBuffer {
            fallToSampleFloor()
        }
        publishAggregatedRendererState()
        attemptNextCandidateIfNeeded()
    }

    private func attemptNextCandidateIfNeeded() {
        guard upscalingEnabled, !thermalThrottled, let ladderPlan, pendingRung == nil else { return }
        guard activeRung == .sampleBuffer else { return }
        guard let nextCandidate = ladderPlanner.nextCandidate(in: ladderPlan, deadRungs: deadRungs) else { return }

        pendingRung = nextCandidate
        let nextAttempt = candidateFailureCounts[nextCandidate, default: 0] + 1
        streamLog(
            "[StreamView] Render ladder attempting \(nextCandidate.rawName) attempt \(nextAttempt)/\(maxCandidateFailureCount) source=\(ladderPlan.sourceDimensions.width)x\(ladderPlan.sourceDimensions.height) target=\(ladderPlan.desiredProcessingTarget.width)x\(ladderPlan.desiredProcessingTarget.height)",
            force: true
        )
        if nextCandidate.usesMetalOutput, metalRenderer == nil {
            handleCandidateFailure(nextCandidate, reason: "Metal renderer unavailable")
            return
        }
        issueRequest(for: nextCandidate)
        updateAttachedRendererFamily()
        publishAggregatedRendererState()
    }

    /// Points both renderers at `rung`; the non-selected renderer goes idle.
    private func issueRequest(for rung: RenderLadderRung) {
        guard let ladderPlan else { return }
        if rung.usesMetalOutput {
            sampleBufferRenderer.setRequestedRung(.sampleBuffer)
            metalRenderer?.setRequest(
                MetalVideoRenderer.RenderRequest(
                    rung: rung,
                    targetWidth: ladderPlan.desiredProcessingTarget.width,
                    targetHeight: ladderPlan.desiredProcessingTarget.height,
                    pacing: pacing
                )
            )
        } else {
            metalRenderer?.setRequest(.idle)
            sampleBufferRenderer.setRequestedRung(rung)
        }
        sampleBufferRenderer.setPacing(lowLatencyMode ? .lowLatency : .smooth)
    }

    private func logCurrentLadderPlan(reason: String) {
        guard let ladderPlan else { return }
        let eligible = ladderPlan.eligibleRungs.map(\.rawName).joined(separator: ", ")
        let skipped: String = {
            guard !ladderPlan.skippedRungReasons.isEmpty else { return "none" }
            return ladderPlan.skippedRungReasons
                .sorted { $0.key < $1.key }
                .map { "\($0.key)=\($0.value)" }
                .joined(separator: "; ")
        }()
        streamLog(
            "[StreamView] Render ladder plan (\(reason)) source=\(ladderPlan.sourceDimensions.width)x\(ladderPlan.sourceDimensions.height) displayTarget=\(ladderPlan.displayTargetDimensions.width)x\(ladderPlan.displayTargetDimensions.height) desiredTarget=\(ladderPlan.desiredProcessingTarget.width)x\(ladderPlan.desiredProcessingTarget.height) eligible=[\(eligible)] skipped={\(skipped)} floor=\(ladderPlan.floorRung.rawName) pacing=\(lowLatencyMode ? "lowLatency" : "smooth")",
            force: true
        )
    }

    private func outputWidthFallback(desiredTarget: RenderLadderDimensions?) -> Int? {
        guard (pendingRung != nil || activeRung != .sampleBuffer), let desiredTarget else { return nil }
        return desiredTarget.width
    }

    private func outputHeightFallback(desiredTarget: RenderLadderDimensions?) -> Int? {
        guard (pendingRung != nil || activeRung != .sampleBuffer), let desiredTarget else { return nil }
        return desiredTarget.height
    }

    // MARK: - Track attachment

    private func applyIfNeeded(videoTrack rawTrack: AnyObject?, containerBounds: CGSize) {
        let newTrack = rawTrack as? RTCVideoTrack
        let trackChanged = attachedTrack !== newTrack
        let frameProbeChanged = lastAppliedFrameProbeEnabled != frameProbeEnabled
        let pacingChanged = lastAppliedLowLatencyMode != lowLatencyMode
        let ladderInputsChanged = lastAppliedUpscalingEnabled != upscalingEnabled
            || lastAppliedFloorBehavior != floorBehavior
            || lastAppliedPreferredUpscaler != preferredUpscaler
            || lastAppliedContainerBounds != containerBounds

        if trackChanged {
            detachRenderers()
            attachedTrack = newTrack
            if newTrack == nil {
                streamLog("[StreamView] detached previous video track")
            }
        }

        guard trackChanged || frameProbeChanged || pacingChanged || ladderInputsChanged else { return }
        lastAppliedUpscalingEnabled = upscalingEnabled
        lastAppliedLowLatencyMode = lowLatencyMode
        lastAppliedFloorBehavior = floorBehavior
        lastAppliedPreferredUpscaler = preferredUpscaler
        lastAppliedFrameProbeEnabled = frameProbeEnabled
        lastAppliedContainerBounds = containerBounds

        if ladderInputsChanged {
            refreshLadderPlan(reason: "settings changed")
        } else if pacingChanged {
            issueRequest(for: pendingRung ?? activeRung)
        }
        if trackChanged || frameProbeChanged {
            updateAttachedRendererFamily()
        }
    }

    private func detachRenderers() {
        guard let attachedTrack else {
            attachedRenderer = .none
            isFrameProbeAttached = false
            return
        }
        switch attachedRenderer {
        case .sampleBuffer:
            attachedTrack.remove(sampleBufferRenderer)
        case .metal:
            if let metalRenderer {
                attachedTrack.remove(metalRenderer)
            }
        case .none:
            break
        }
        attachedRenderer = .none
        if isFrameProbeAttached {
            attachedTrack.remove(frameProbe)
            isFrameProbeAttached = false
        }
    }

    /// Attaches the renderer that owns the pending/active rung; no-op when it is already attached.
    private func updateAttachedRendererFamily() {
        guard let attachedTrack else { return }
        let desired: AttachedRenderer = {
            guard upscalingEnabled, !thermalThrottled, let metalRenderer else { return .sampleBuffer }
            _ = metalRenderer
            return (pendingRung ?? activeRung).usesMetalOutput ? .metal : .sampleBuffer
        }()

        if desired != attachedRenderer {
            switch attachedRenderer {
            case .sampleBuffer:
                attachedTrack.remove(sampleBufferRenderer)
            case .metal:
                if let metalRenderer {
                    attachedTrack.remove(metalRenderer)
                }
            case .none:
                break
            }
            switch desired {
            case .metal:
                if let metalRenderer {
                    attachedTrack.add(metalRenderer)
                }
            case .sampleBuffer:
                attachedTrack.add(sampleBufferRenderer)
            case .none:
                break
            }
            attachedRenderer = desired
        }

        if shouldAttachFrameProbe != isFrameProbeAttached {
            if shouldAttachFrameProbe {
                attachedTrack.add(frameProbe)
            } else {
                attachedTrack.remove(frameProbe)
            }
            isFrameProbeAttached = shouldAttachFrameProbe
        }
    }

    // MARK: - Thermal pressure

    /// Drops to the cheapest presentation path while the device is hot and climbs back afterwards.
    private func startThermalObservationIfNeeded() {
        guard thermalObservation == nil else { return }
        applyThermalState(ProcessInfo.processInfo.thermalState)
        thermalObservation = Task { [weak self] in
            let notifications = NotificationCenter.default.notifications(named: ProcessInfo.thermalStateDidChangeNotification)
            for await _ in notifications {
                guard let self else { return }
                self.applyThermalState(ProcessInfo.processInfo.thermalState)
            }
        }
    }

    private func applyThermalState(_ state: ProcessInfo.ThermalState) {
        let shouldThrottle: Bool
        switch state {
        case .serious, .critical:
            shouldThrottle = true
        case .nominal, .fair:
            shouldThrottle = false
        @unknown default:
            shouldThrottle = false
        }
        guard shouldThrottle != thermalThrottled else { return }
        thermalThrottled = shouldThrottle
        streamLog("[StreamView] thermal state \(state.rawValue): upscaling \(shouldThrottle ? "suspended" : "resumed")", force: true)
        if shouldThrottle {
            if activeRung != .sampleBuffer || pendingRung != nil {
                fallToSampleFloor()
            }
            publishAggregatedRendererState()
        } else {
            refreshLadderPlan(reason: "thermal recovery")
        }
    }

    // MARK: - Display mode

    /// Asks tvOS to switch the TV to a 60 Hz SDR mode matching the stream, so a 50 Hz or
    /// HDR-always-on default cannot judder or tone-map a 60 fps SDR game stream. Honoured only
    /// when the user enabled "Match Content" in tvOS settings.
    private func applyDisplayCriteriaIfNeeded(width: Int, height: Int) {
#if canImport(AVKit) && os(tvOS)
        guard !didApplyDisplayCriteria, let window = container?.window else { return }
        var formatDescription: CMFormatDescription?
        let extensions: [CFString: Any] = [
            kCMFormatDescriptionExtension_ColorPrimaries: kCMFormatDescriptionColorPrimaries_ITU_R_709_2,
            kCMFormatDescriptionExtension_TransferFunction: kCMFormatDescriptionTransferFunction_ITU_R_709_2,
            kCMFormatDescriptionExtension_YCbCrMatrix: kCMFormatDescriptionYCbCrMatrix_ITU_R_709_2
        ]
        let status = CMVideoFormatDescriptionCreate(
            allocator: kCFAllocatorDefault,
            codecType: kCMVideoCodecType_H264,
            width: Int32(width),
            height: Int32(height),
            extensions: extensions as CFDictionary,
            formatDescriptionOut: &formatDescription
        )
        guard status == noErr, let formatDescription else { return }
        didApplyDisplayCriteria = true
        let displayManager = window.avDisplayManager
        displayManager.preferredDisplayCriteria = AVDisplayCriteria(refreshRate: 60, formatDescription: formatDescription)
        streamLog(
            "[StreamView] requested 60 Hz SDR display mode (matching enabled: \(displayManager.isDisplayCriteriaMatchingEnabled))",
            force: true
        )
#endif
    }

    private func clearDisplayCriteria() {
#if canImport(AVKit) && os(tvOS)
        guard didApplyDisplayCriteria else { return }
        didApplyDisplayCriteria = false
        container?.window?.avDisplayManager.preferredDisplayCriteria = nil
#endif
    }
}
#endif

