//
//  SampleBufferDisplayRenderer.swift
//  Northstar
//
//  Sample-buffer presentation path: decoded frames go straight from the WebRTC decode thread
//  into an AVSampleBufferVideoRenderer receiver (tvOS 27 API) with host-clock timestamps, so
//  presentation is paced by the media pipeline and never waits on the main thread. Also hosts
//  the VideoToolbox low-latency super-resolution rung, whose output takes the same route.
//

#if WEBRTC_AVAILABLE && canImport(UIKit) && canImport(AVFoundation)
import Foundation
@preconcurrency import AVFoundation
@preconcurrency import CoreMedia
#if canImport(VideoToolbox)
@preconcurrency import VideoToolbox
#endif
import NorthstarCore
import VideoRenderingKit
import UIKit

/// How presentation is timed relative to frame arrival, shared by both renderers.
enum StreamPresentationPacing: Sendable, Equatable {
    /// Present on a steady cadence; bursts become consecutive frames at the cost of up to one
    /// display interval of latency.
    case smooth
    /// Present as soon as a frame is available; lowest input latency, less even motion.
    case lowLatency
}

/// Thread-safety contract (the reason this is `@unchecked Sendable`):
/// - `stateLock` guards every mutable property below except the `on*` callbacks and `displayLayer`.
/// - Callbacks are assigned by the coordinator before the renderer is attached to a track and are
///   only invoked from the WebRTC decode thread or VideoToolbox completion handlers.
/// - `displayLayer` is main-actor state (it is `@MainActor` in the tvOS 27 SDK); it is only used
///   inside `@MainActor` methods. Enqueueing goes through the `Sendable` receiver instead.
final class SampleBufferDisplayRenderer: NSObject, RTCVideoRenderer, @unchecked Sendable {
    @MainActor weak var displayLayer: AVSampleBufferDisplayLayer?
    let stateLock = NSLock()
    let rendererDebugID = String(UUID().uuidString.prefix(6))

    // Presentation
    var receiver: AVSampleBufferVideoRenderer.Receiver?
    var synchronizer: AVSampleBufferRenderSynchronizer?
    var pacing: StreamPresentationPacing = .smooth
    var hdrEnabled = true
    var cachedFormatDescription: CMVideoFormatDescription?
    var consecutiveEnqueueFailures = 0
    var didReportDecodeFailure = false
    var didLogUnsupportedBufferType = false
    var didLogIncomingCVPixelBufferDetails = false
    var didLogFirstEnqueue = false
    var didReportFirstDraw = false

    // Counters / telemetry
    var framesReceived = 0
    var framesDrawn = 0
    var framesDroppedByCoalescing = 0
    var drawQueueDepthMax = 0
    var framesFailed = 0
    var processingStatus: String?
    var processingInputWidth: Int?
    var processingInputHeight: Int?
    var processingOutputWidth: Int?
    var processingOutputHeight: Int?
    var renderLatencyMs: Double?
    var lastError: String?
    var lastTelemetryEmitTime: TimeInterval = Date.timeIntervalSinceReferenceDate
    var lastSourceWidth = 0
    var lastSourceHeight = 0
    var displayTargetWidth: Int?
    var displayTargetHeight: Int?

    // Ladder
    var requestedRung: RenderLadderRung = .sampleBuffer
    var lastReadyRung: RenderLadderRung?
    var lastFailedRung: RenderLadderRung?

    // Low-latency super resolution (see SampleBufferDisplayRendererLowLatencySuperResolution.swift)
    var llsrInFlightCount = 0
    var pendingLLSRFrame: (pixelBuffer: CVPixelBuffer, arrivalTime: TimeInterval)?
    var currentLLSRGeneration: UInt64 = 0
    var llsrSessionStartInProgress = false
    var llsrFallbackToPlainSampleBuffer = false
    var llsrDisplayActivated = false
    var didLogFirstLLSRFrame = false
    var didLogLLSRSourceCopy = false
#if canImport(VideoToolbox) && !targetEnvironment(simulator)
    var activeLowLatencySuperResolutionResources: LowLatencySuperResolutionResources?
#endif

    var onDecodeFailure: (@Sendable (String) -> Void)?
    /// Fired once per source-dimension change (not per frame).
    var onSourceDimensionsChanged: (@Sendable (Int, Int) -> Void)?
    var onCandidateReady: (@Sendable (RenderLadderRung) -> Void)?
    var onCandidateFailed: (@Sendable (RenderLadderRung, String) -> Void)?
    var onTelemetry: (@Sendable (TelemetrySnapshot) -> Void)?
    var onFirstFrameDrawn: (@Sendable () -> Void)?

    /// Frames in flight in the LLSR processor before newer arrivals replace the queued one.
    static let maxLLSRFramesInFlight = 2
    /// Nominal stream frame interval used for pacing timestamps.
    static let nominalFrameDuration: TimeInterval = 1.0 / 60.0

    // MARK: - Telemetry

    /// Captures the renderer counters and last-known processing state exposed to diagnostics.
    struct TelemetrySnapshot: Equatable, Sendable {
        let framesReceived: Int?
        let framesDrawn: Int?
        let framesDroppedByCoalescing: Int?
        let drawQueueDepthMax: Int?
        let framesFailed: Int?
        let processingStatus: String?
        let processingInputWidth: Int?
        let processingInputHeight: Int?
        let processingOutputWidth: Int?
        let processingOutputHeight: Int?
        let renderLatencyMs: Double?
        let lastError: String?
    }

    /// Emits renderer debug logs only when verbose diagnostics are enabled or forced.
    func streamLog(_ message: @autoclosure () -> String, force: Bool = false) {
        guard force || SettingsStore.snapshotDiagnostics().verboseLogs else { return }
        print(message())
    }

    /// Ignores RTC size callbacks because the display layer follows its host view size instead.
    func setSize(_ size: CGSize) {
        // AVSampleBufferDisplayLayer sizes with its host view.
    }

    /// Ingests the latest WebRTC frame and routes it through super-resolution or plain display.
    func renderFrame(_ frame: RTCVideoFrame?) {
        guard let frame else { return }
        guard let cvPixelBuffer = (frame.buffer as? RTCCVPixelBuffer)?.pixelBuffer else {
            if !didLogUnsupportedBufferType {
                didLogUnsupportedBufferType = true
                streamLog("[StreamView] SampleBuffer renderer unsupported buffer type: \(type(of: frame.buffer))")
            }
            return
        }
        if !didLogIncomingCVPixelBufferDetails {
            didLogIncomingCVPixelBufferDetails = true
            let inputPixelFormat = pixelFormatDescription(CVPixelBufferGetPixelFormatType(cvPixelBuffer))
            let creationAttributes = (CVPixelBufferCopyCreationAttributes(cvPixelBuffer) as? [String: Any])
                .map(lowLatencyAttributeSummary) ?? "unavailable"
            let colorAttachments = pixelBufferColorAttachmentSummary(cvPixelBuffer)
            streamLog("[StreamView][SBR \(rendererDebugID)] first WebRTC CVPixelBuffer format=\(inputPixelFormat) attrs={\(creationAttributes)} attachments={\(colorAttachments)}", force: true)
        }

        let width = CVPixelBufferGetWidth(cvPixelBuffer)
        let height = CVPixelBufferGetHeight(cvPixelBuffer)
        let arrivalTime = Date.timeIntervalSinceReferenceDate

        stateLock.lock()
        framesReceived += 1
        let dimensionsChanged = width != lastSourceWidth || height != lastSourceHeight
        if dimensionsChanged {
            lastSourceWidth = width
            lastSourceHeight = height
        }
        let rung = requestedRung
        let superResolutionActive = llsrDisplayActivated
        stateLock.unlock()

        if dimensionsChanged {
            onSourceDimensionsChanged?(width, height)
        }

        if case .vtSuperResolution(let scaleFactor) = rung {
#if canImport(VideoToolbox) && !targetEnvironment(simulator)
            submitLowLatencySuperResolutionFrame(
                cvPixelBuffer,
                arrivalTime: arrivalTime,
                scaleFactor: scaleFactor
            )
#endif
        }

        // Until super resolution has produced its first frame, the source frame is shown as is.
        guard !superResolutionActive else {
            emitTelemetryIfNeeded()
            return
        }
        enqueue(pixelBuffer: cvPixelBuffer, arrivalTime: arrivalTime)
        emitTelemetryIfNeeded()
    }
}
#endif

// SampleBufferDisplayRendererPlainPipeline.swift
// Defines sample buffer display renderer plain pipeline for the Features / Streaming surface.
//

#if WEBRTC_AVAILABLE && canImport(UIKit) && canImport(AVFoundation)
import Foundation
@preconcurrency import AVFoundation
@preconcurrency import CoreMedia
import NorthstarCore
import VideoRenderingKit

extension SampleBufferDisplayRenderer {
    /// Hands one pixel buffer to the video renderer from the calling (decode) thread.
    func enqueue(pixelBuffer: CVPixelBuffer, arrivalTime: TimeInterval) {
        stateLock.lock()
        let receiver = self.receiver
        let pacing = self.pacing
        stateLock.unlock()
        guard let receiver else { return }

        let presentationTimeStamp = presentationTimeStamp(pacing: pacing)
        guard let sampleBuffer = makeReadySampleBuffer(from: pixelBuffer, presentationTimeStamp: presentationTimeStamp) else {
            return
        }

        let result = receiver.enqueueImmediately(sampleBuffer)
        var failureDescription: String?
        var requiresFlush = false
        switch result {
        case .enqueued:
            break
        case .enqueuedWithDecodeFailures(let errors):
            failureDescription = errors.first.map { "decode failure: \($0.localizedDescription)" } ?? "decode failure"
        case .cancelledDueToFlush:
            return
        case .cancelledDueToFlushRequiredToResume(let error):
            failureDescription = "renderer requires flush: \(error.localizedDescription)"
            requiresFlush = true
        case .cancelledDueToError(let error):
            failureDescription = "enqueue failed: \(error.localizedDescription)"
        @unknown default:
            break
        }

        if let failureDescription {
            handleEnqueueFailure(failureDescription, requiresFlush: requiresFlush)
            return
        }

        let shouldReportFirstDraw: Bool
        stateLock.lock()
        consecutiveEnqueueFailures = 0
        framesDrawn += 1
        shouldReportFirstDraw = !didReportFirstDraw
        didReportFirstDraw = true
        renderLatencyMs = (Date.timeIntervalSinceReferenceDate - arrivalTime) * 1_000
        stateLock.unlock()

        if shouldReportFirstDraw {
            onFirstFrameDrawn?()
        }
        if !didLogFirstEnqueue {
            didLogFirstEnqueue = true
            streamLog("[StreamView] SampleBufferDisplayLayer first enqueue")
        }
    }

    private func handleEnqueueFailure(_ description: String, requiresFlush: Bool) {
        let shouldReport: Bool
        stateLock.lock()
        framesFailed += 1
        consecutiveEnqueueFailures += 1
        lastError = description
        shouldReport = consecutiveEnqueueFailures >= 3 && !didReportDecodeFailure
        if shouldReport {
            didReportDecodeFailure = true
        }
        let receiver = self.receiver
        stateLock.unlock()

        streamLog("[StreamView] SampleBuffer enqueue failed: \(description)", force: true)
        if requiresFlush {
            receiver?.flush()
        }
        if shouldReport {
            onDecodeFailure?("AVSampleBufferVideoRenderer failed repeatedly: \(description)")
        }
    }

    /// Timestamps frames against the synchronizer's host-clock timebase.
    ///
    /// `.smooth` schedules each frame one nominal interval plus a half-interval jitter allowance
    /// ahead, so arrival jitter below that budget never changes the display cadence.
    /// `.lowLatency` schedules for "now", which the renderer shows at the next refresh.
    private func presentationTimeStamp(pacing: StreamPresentationPacing) -> CMTime {
        let now = CMClockGetTime(CMClockGetHostTimeClock())
        switch pacing {
        case .lowLatency:
            return now
        case .smooth:
            return now + CMTime(seconds: Self.nominalFrameDuration * 1.5, preferredTimescale: 1_000_000)
        }
    }

    func makeReadySampleBuffer(
        from pixelBuffer: CVPixelBuffer,
        presentationTimeStamp: CMTime
    ) -> CMReadySampleBuffer<CMSampleBuffer.DynamicContent>? {
        applyPreferredColorAttachments(to: pixelBuffer)

        guard let formatDescription = formatDescription(for: pixelBuffer) else {
            return nil
        }

        var timing = CMSampleTimingInfo(
            duration: CMTime(value: 1, timescale: 60),
            presentationTimeStamp: presentationTimeStamp,
            decodeTimeStamp: .invalid
        )

        var sampleBuffer: CMSampleBuffer?
        let sampleStatus = CMSampleBufferCreateReadyWithImageBuffer(
            allocator: kCFAllocatorDefault,
            imageBuffer: pixelBuffer,
            formatDescription: formatDescription,
            sampleTiming: &timing,
            sampleBufferOut: &sampleBuffer
        )
        guard sampleStatus == noErr, let sampleBuffer else {
            streamLog("[StreamView] SampleBuffer creation failed: \(sampleStatus)", force: true)
            return nil
        }
        pixelBuffer.propagateAttachments(to: sampleBuffer)

        let readyBuffer = CMReadySampleBuffer<CVReadOnlyPixelBuffer>(unsafeWithPixelBuffer: sampleBuffer)
        return CMReadySampleBuffer<CMSampleBuffer.DynamicContent>(readyBuffer)
    }

    /// Reuses the format description while consecutive frames share dimensions and format.
    private func formatDescription(for pixelBuffer: CVPixelBuffer) -> CMVideoFormatDescription? {
        stateLock.lock()
        let cached = cachedFormatDescription
        stateLock.unlock()
        if let cached, CMVideoFormatDescriptionMatchesImageBuffer(cached, imageBuffer: pixelBuffer) {
            return cached
        }

        var formatDescription: CMFormatDescription?
        let descStatus = CMVideoFormatDescriptionCreateForImageBuffer(
            allocator: kCFAllocatorDefault,
            imageBuffer: pixelBuffer,
            formatDescriptionOut: &formatDescription
        )
        guard descStatus == noErr, let formatDescription else {
            streamLog("[StreamView] SampleBuffer format description failed: \(descStatus)", force: true)
            return nil
        }
        stateLock.lock()
        cachedFormatDescription = formatDescription
        stateLock.unlock()
        return formatDescription
    }

    func applyPreferredColorAttachments(to pixelBuffer: CVPixelBuffer) {
        stateLock.lock()
        let hdrEnabled = self.hdrEnabled
        stateLock.unlock()

        let pixelFormat = CVPixelBufferGetPixelFormatType(pixelBuffer)
        let is10bit = pixelFormat == kCVPixelFormatType_420YpCbCr10BiPlanarVideoRange
            || pixelFormat == kCVPixelFormatType_420YpCbCr10BiPlanarFullRange
        let is8BitBiPlanar = pixelFormat == kCVPixelFormatType_420YpCbCr8BiPlanarVideoRange
            || pixelFormat == kCVPixelFormatType_420YpCbCr8BiPlanarFullRange

        if hdrEnabled && is10bit {
            CVBufferSetAttachment(pixelBuffer,
                                  kCVImageBufferColorPrimariesKey,
                                  kCVImageBufferColorPrimaries_ITU_R_2020,
                                  .shouldPropagate)
            CVBufferSetAttachment(pixelBuffer,
                                  kCVImageBufferTransferFunctionKey,
                                  kCVImageBufferTransferFunction_SMPTE_ST_2084_PQ,
                                  .shouldPropagate)
            CVBufferSetAttachment(pixelBuffer,
                                  kCVImageBufferYCbCrMatrixKey,
                                  kCVImageBufferYCbCrMatrix_ITU_R_2020,
                                  .shouldPropagate)
            return
        }

        guard is8BitBiPlanar else { return }
        CVBufferSetAttachment(pixelBuffer,
                              kCVImageBufferColorPrimariesKey,
                              kCVImageBufferColorPrimaries_ITU_R_709_2,
                              .shouldPropagate)
        CVBufferSetAttachment(pixelBuffer,
                              kCVImageBufferTransferFunctionKey,
                              kCVImageBufferTransferFunction_ITU_R_709_2,
                              .shouldPropagate)
        CVBufferSetAttachment(pixelBuffer,
                              kCVImageBufferYCbCrMatrixKey,
                              kCVImageBufferYCbCrMatrix_ITU_R_709_2,
                              .shouldPropagate)
    }

    func copyDisplayAttachments(from sourceBuffer: CVImageBuffer, to destinationBuffer: CVImageBuffer) {
        if let propagatingAttachments = CVBufferCopyAttachments(sourceBuffer, .shouldPropagate) {
            CVBufferSetAttachments(destinationBuffer, propagatingAttachments, .shouldPropagate)
        }
        if let nonPropagatingAttachments = CVBufferCopyAttachments(sourceBuffer, .shouldNotPropagate) {
            CVBufferSetAttachments(destinationBuffer, nonPropagatingAttachments, .shouldNotPropagate)
        }
    }

    func pixelFormatDescription(_ pixelFormat: OSType) -> String {
        let bytes: [UInt8] = [
            UInt8((pixelFormat >> 24) & 0xff),
            UInt8((pixelFormat >> 16) & 0xff),
            UInt8((pixelFormat >> 8) & 0xff),
            UInt8(pixelFormat & 0xff)
        ]
        let ascii = String(bytes: bytes, encoding: .ascii)?
            .trimmingCharacters(in: .controlCharacters.union(.whitespacesAndNewlines)) ?? ""
        if ascii.isEmpty {
            return "\(pixelFormat)"
        }
        return "\(ascii) (\(pixelFormat))"
    }

    func pixelBufferColorAttachmentSummary(_ pixelBuffer: CVPixelBuffer) -> String {
        let keys: [(CFString, String)] = [
            (kCVImageBufferColorPrimariesKey, "primaries"),
            (kCVImageBufferTransferFunctionKey, "transfer"),
            (kCVImageBufferYCbCrMatrixKey, "matrix")
        ]
        let parts = keys.compactMap { key, label -> String? in
            guard let value = CVBufferCopyAttachment(pixelBuffer, key, nil) else { return nil }
            return "\(label)=\(value)"
        }
        return parts.isEmpty ? "none" : parts.joined(separator: " ")
    }

    func lowLatencyAttributeSummary(_ attributes: [String: Any]) -> String {
        let pixelFormatKey = kCVPixelBufferPixelFormatTypeKey as String
        let iosurfaceKey = kCVPixelBufferIOSurfacePropertiesKey as String
        let interestingKeys = [
            pixelFormatKey,
            kCVPixelBufferWidthKey as String,
            kCVPixelBufferHeightKey as String,
            iosurfaceKey,
            kCVPixelBufferMetalCompatibilityKey as String,
            kCVPixelBufferExtendedPixelsLeftKey as String,
            kCVPixelBufferExtendedPixelsTopKey as String,
            kCVPixelBufferExtendedPixelsRightKey as String,
            kCVPixelBufferExtendedPixelsBottomKey as String
        ]

        var parts: [String] = []
        for key in interestingKeys {
            guard let value = attributes[key] else { continue }
            switch key {
            case pixelFormatKey:
                if let number = value as? NSNumber {
                    parts.append("pixelFormat=\(pixelFormatDescription(OSType(truncating: number)))")
                } else {
                    parts.append("pixelFormat=\(value)")
                }
            case iosurfaceKey:
                if let dictionary = value as? [String: Any] {
                    parts.append("iosurfaceKeys=[\(dictionary.keys.sorted().joined(separator: ","))]")
                } else {
                    parts.append("iosurface=\(value)")
                }
            default:
                parts.append("\(key)=\(value)")
            }
        }

        let remainingKeys = attributes.keys
            .filter { !interestingKeys.contains($0) }
            .sorted()
        if !remainingKeys.isEmpty {
            parts.append("otherKeys=[\(remainingKeys.joined(separator: ","))]")
        }
        return parts.joined(separator: " ")
    }

    private var telemetrySnapshot: TelemetrySnapshot {
        stateLock.lock()
        defer { stateLock.unlock() }
        return TelemetrySnapshot(
            framesReceived: framesReceived,
            framesDrawn: framesDrawn,
            framesDroppedByCoalescing: framesDroppedByCoalescing,
            drawQueueDepthMax: drawQueueDepthMax,
            framesFailed: framesFailed,
            processingStatus: processingStatus,
            processingInputWidth: processingInputWidth,
            processingInputHeight: processingInputHeight,
            processingOutputWidth: processingOutputWidth,
            processingOutputHeight: processingOutputHeight,
            renderLatencyMs: renderLatencyMs,
            lastError: lastError
        )
    }

    func emitTelemetryIfNeeded(force: Bool = false) {
        let now = Date.timeIntervalSinceReferenceDate
        stateLock.lock()
        let due = force || now - lastTelemetryEmitTime >= 1
        if due {
            lastTelemetryEmitTime = now
        }
        stateLock.unlock()
        guard due else { return }
        onTelemetry?(telemetrySnapshot)
    }

    func reportCandidateReadyIfNeeded(_ rung: RenderLadderRung) {
        stateLock.lock()
        let alreadyReady = lastReadyRung == rung
        if !alreadyReady {
            lastReadyRung = rung
            lastFailedRung = nil
        }
        stateLock.unlock()
        guard !alreadyReady else { return }
        onCandidateReady?(rung)
    }

    func reportCandidateFailureIfNeeded(_ rung: RenderLadderRung, reason: String) {
        stateLock.lock()
        let alreadyFailed = lastFailedRung == rung
        if !alreadyFailed {
            lastFailedRung = rung
            lastError = reason
        }
        stateLock.unlock()
        guard !alreadyFailed else { return }
        onCandidateFailed?(rung, reason)
    }
}
#endif

// SampleBufferDisplayRendererLifecycle.swift
// Defines sample buffer display renderer lifecycle for the Features / Streaming surface.
//

#if WEBRTC_AVAILABLE && canImport(UIKit) && canImport(AVFoundation)
import Foundation
@preconcurrency import AVFoundation
@preconcurrency import CoreMedia
#if canImport(VideoToolbox)
@preconcurrency import VideoToolbox
#endif
import NorthstarCore
import VideoRenderingKit
import UIKit

extension SampleBufferDisplayRenderer {
    func setRequestedRung(_ rung: RenderLadderRung) {
        stateLock.lock()
        let changed = requestedRung != rung
        requestedRung = rung
        if changed {
            lastReadyRung = nil
            lastFailedRung = nil
            lastError = nil
        }
        let sourceWidth = lastSourceWidth
        let sourceHeight = lastSourceHeight
        stateLock.unlock()
        guard changed else { return }

        resetLowLatencySuperResolutionState()
        switch rung {
        case .vtSuperResolution(let scaleFactor):
#if canImport(VideoToolbox) && !targetEnvironment(simulator)
            // Warm the ML session off the decode thread so the first frames do not stall.
            if sourceWidth > 0, sourceHeight > 0 {
                startLowLatencySuperResolutionSessionIfNeeded(
                    width: sourceWidth,
                    height: sourceHeight,
                    scaleFactor: scaleFactor
                )
            }
#else
            _ = scaleFactor
#endif
        case .sampleBuffer:
            updateLowLatencyStatus(nil, inputWidth: nil, inputHeight: nil, outputWidth: nil, outputHeight: nil)
        case .metalFXSpatial, .passthrough:
            break
        }
    }

    func setPacing(_ newPacing: StreamPresentationPacing) {
        stateLock.lock()
        pacing = newPacing
        stateLock.unlock()
    }

    func setHDREnabled(_ enabled: Bool) {
        stateLock.lock()
        hdrEnabled = enabled
        stateLock.unlock()
    }

    /// Binds the renderer to its layer and starts the host-clock timebase frames are stamped against.
    @MainActor
    func bind(to displayView: SampleBufferDisplayView) {
        let displayLayer = displayView.displayLayer
        self.displayLayer = displayLayer
        displayLayer.videoGravity = .resizeAspect

        let synchronizer = AVSampleBufferRenderSynchronizer()
        let receiver = synchronizer.sampleBufferReceiver(adding: displayLayer.sampleBufferRenderer)
        // Rate 1 anchored to the host clock makes synchronizer time == host time, so frames can be
        // stamped with host-clock timestamps from any thread.
        synchronizer.setRate(1, time: CMClockGetTime(CMClockGetHostTimeClock()))

        let displayTarget = displayView.displayTargetDimensions
        stateLock.lock()
        self.synchronizer = synchronizer
        self.receiver = receiver
        displayTargetWidth = displayTarget.width
        displayTargetHeight = displayTarget.height
        consecutiveEnqueueFailures = 0
        didReportDecodeFailure = false
        stateLock.unlock()
        streamLog("[StreamView][SBR \(rendererDebugID)] sample-buffer receiver bound", force: true)
        emitTelemetryIfNeeded(force: true)
    }

    @MainActor
    func updateDisplayTarget(from displayView: SampleBufferDisplayView) {
        let displayTarget = displayView.displayTargetDimensions
        updateDisplayTargetDimensions(width: displayTarget.width, height: displayTarget.height)
    }

    func flushDisplayLayer(removingDisplayedImage: Bool) {
        stateLock.lock()
        let receiver = self.receiver
        stateLock.unlock()
        guard let receiver else { return }
        if removingDisplayedImage {
            Task {
                await receiver.flush(removingDisplayedImage: true)
            }
        } else {
            receiver.flush()
        }
    }

    func reset() {
        stateLock.lock()
        consecutiveEnqueueFailures = 0
        didReportDecodeFailure = false
        didReportFirstDraw = false
        framesReceived = 0
        framesDrawn = 0
        framesDroppedByCoalescing = 0
        drawQueueDepthMax = 0
        framesFailed = 0
        processingStatus = nil
        processingInputWidth = nil
        processingInputHeight = nil
        processingOutputWidth = nil
        processingOutputHeight = nil
        lastError = nil
        displayTargetWidth = nil
        displayTargetHeight = nil
        renderLatencyMs = nil
        lastSourceWidth = 0
        lastSourceHeight = 0
        cachedFormatDescription = nil
        lastReadyRung = nil
        lastFailedRung = nil
        requestedRung = .sampleBuffer
        didLogIncomingCVPixelBufferDetails = false
        stateLock.unlock()
        resetLowLatencySuperResolutionState()
        streamLog("[StreamView][SBR \(rendererDebugID)] reset", force: true)
        flushDisplayLayer(removingDisplayedImage: true)
    }
}
#endif

//
//  SampleBufferDisplayRendererLowLatencySupport.swift
//  Northstar
//
//  Shared low-latency VideoToolbox support for the sample-buffer renderer.
//

#if WEBRTC_AVAILABLE && canImport(UIKit) && canImport(AVFoundation)
import Foundation
@preconcurrency import AVFoundation
@preconcurrency import CoreMedia
#if canImport(VideoToolbox)
@preconcurrency import VideoToolbox
#endif
import UIKit

extension SampleBufferDisplayRenderer {
#if canImport(VideoToolbox) && !targetEnvironment(simulator)
    /// One VTFrameProcessor session plus the pools that feed it. Immutable after creation.
    ///
    /// `@unchecked Sendable`: every stored property is a `let`; VideoToolbox sessions and pixel
    /// buffer pools are internally thread-safe for the create/process/end usage here.
    final class LowLatencySuperResolutionResources: @unchecked Sendable {
        let sourceWidth: Int
        let sourceHeight: Int
        let outputWidth: Int
        let outputHeight: Int
        let scaleFactor: Float
        let generation: UInt64
        let configuration: VTLowLatencySuperResolutionScalerConfiguration
        let processor: VTFrameProcessor
        let sourcePool: CVPixelBufferPool
        let destinationPool: CVPixelBufferPool
        let pixelTransferSession: VTPixelTransferSession

        init(
            sourceWidth: Int,
            sourceHeight: Int,
            outputWidth: Int,
            outputHeight: Int,
            scaleFactor: Float,
            generation: UInt64,
            configuration: VTLowLatencySuperResolutionScalerConfiguration,
            processor: VTFrameProcessor,
            sourcePool: CVPixelBufferPool,
            destinationPool: CVPixelBufferPool,
            pixelTransferSession: VTPixelTransferSession
        ) {
            self.sourceWidth = sourceWidth
            self.sourceHeight = sourceHeight
            self.outputWidth = outputWidth
            self.outputHeight = outputHeight
            self.scaleFactor = scaleFactor
            self.generation = generation
            self.configuration = configuration
            self.processor = processor
            self.sourcePool = sourcePool
            self.destinationPool = destinationPool
            self.pixelTransferSession = pixelTransferSession
        }

        deinit {
            processor.endSession()
            VTPixelTransferSessionInvalidate(pixelTransferSession)
        }
    }
#endif

    func resetLowLatencySuperResolutionState() {
        stateLock.lock()
        pendingLLSRFrame = nil
        llsrInFlightCount = 0
        currentLLSRGeneration &+= 1
        llsrSessionStartInProgress = false
        llsrFallbackToPlainSampleBuffer = false
        llsrDisplayActivated = false
        didLogFirstLLSRFrame = false
        didLogLLSRSourceCopy = false
#if canImport(VideoToolbox) && !targetEnvironment(simulator)
        activeLowLatencySuperResolutionResources = nil
#endif
        stateLock.unlock()
    }

    func updateLowLatencyStatus(
        _ status: String?,
        inputWidth: Int?,
        inputHeight: Int?,
        outputWidth: Int?,
        outputHeight: Int?,
        lastError: String? = nil
    ) {
        stateLock.lock()
        processingStatus = status
        processingInputWidth = inputWidth
        processingInputHeight = inputHeight
        processingOutputWidth = outputWidth
        processingOutputHeight = outputHeight
        if let lastError {
            self.lastError = lastError
        }
        stateLock.unlock()
    }

    func updateDisplayTargetDimensions(
        width: Int?,
        height: Int?
    ) {
        stateLock.lock()
        displayTargetWidth = width
        displayTargetHeight = height
        stateLock.unlock()
    }

#if canImport(VideoToolbox) && !targetEnvironment(simulator)
    func lowLatencyErrorDetails(_ error: Error) -> String {
        let nsError = error as NSError
        var parts = [
            "domain=\(nsError.domain)",
            "code=\(nsError.code)"
        ]

        if nsError.domain == VTFrameProcessorErrorDomain,
           let frameProcessorCode = VTFrameProcessorError.Code(rawValue: nsError.code) {
            parts.append("vtCode=\(String(describing: frameProcessorCode))")
        }

        parts.append("description=\(nsError.localizedDescription)")

        if let failureReason = nsError.localizedFailureReason, !failureReason.isEmpty {
            parts.append("failureReason=\(failureReason)")
        }
        if let underlyingError = nsError.userInfo[NSUnderlyingErrorKey] as? NSError {
            parts.append("underlying={domain=\(underlyingError.domain) code=\(underlyingError.code) description=\(underlyingError.localizedDescription)}")
        }
        return parts.joined(separator: " ")
    }

    func isLowLatencyInitializationError(_ error: Error) -> Bool {
        let nsError = error as NSError
        guard nsError.domain == VTFrameProcessorErrorDomain else {
            return nsError.localizedDescription == "Processor is not initialized"
        }
        if let code = VTFrameProcessorError.Code(rawValue: nsError.code),
           code == .sessionNotStarted || code == .initializationFailed {
            return true
        }
        return nsError.localizedDescription == "Processor is not initialized"
    }

    func makeResolvedPixelBufferAttributes(
        baseAttributes: [String: Any],
        width: Int,
        height: Int,
        pixelFormat: OSType?,
        label: String
    ) throws -> CFDictionary {
        var concreteAttributes: [String: Any] = [
            kCVPixelBufferWidthKey as String: width,
            kCVPixelBufferHeightKey as String: height,
            kCVPixelBufferIOSurfacePropertiesKey as String: [:]
        ]
        if let pixelFormat,
           baseAttributes[kCVPixelBufferPixelFormatTypeKey as String] == nil {
            concreteAttributes[kCVPixelBufferPixelFormatTypeKey as String] = pixelFormat
        }

        var resolvedAttributes: CFDictionary?
        let resolveStatus = CVPixelBufferCreateResolvedAttributesDictionary(
            kCFAllocatorDefault,
            [baseAttributes as CFDictionary, concreteAttributes as CFDictionary] as CFArray,
            &resolvedAttributes
        )
        guard resolveStatus == kCVReturnSuccess, let resolvedAttributes else {
            throw NSError(
                domain: "StreamView.LowLatencySuperResolution",
                code: Int(resolveStatus),
                userInfo: [NSLocalizedDescriptionKey: "\(label) attribute resolution failed: \(resolveStatus)"]
            )
        }
        return resolvedAttributes
    }

    func lowLatencySourceBufferNeedsCopy(
        _ pixelBuffer: CVPixelBuffer,
        requiredAttributes: [String: Any]
    ) -> Bool {
        if let desiredPixelFormatNumber = requiredAttributes[kCVPixelBufferPixelFormatTypeKey as String] as? NSNumber {
            let desiredPixelFormat = OSType(truncating: desiredPixelFormatNumber)
            let actualPixelFormat = CVPixelBufferGetPixelFormatType(pixelBuffer)
            if actualPixelFormat != desiredPixelFormat {
                return true
            }
        }

        guard let creationAttributes = CVPixelBufferCopyCreationAttributes(pixelBuffer) as? [String: Any] else {
            return true
        }

        let criticalKeys = [
            kCVPixelBufferExtendedPixelsLeftKey as String,
            kCVPixelBufferExtendedPixelsTopKey as String,
            kCVPixelBufferExtendedPixelsRightKey as String,
            kCVPixelBufferExtendedPixelsBottomKey as String
        ]

        for key in criticalKeys {
            if let desiredValue = requiredAttributes[key] as? Int {
                let receivedValue = (creationAttributes[key] as? Int) ?? 0
                if receivedValue != desiredValue {
                    return true
                }
            }
        }

        return false
    }
#endif
}

#endif

//
//  SampleBufferDisplayRendererLowLatencySuperResolution.swift
//  Northstar
//
//  Low-latency super-resolution rung for the sample-buffer renderer. Sessions start off the
//  decode thread, up to two frames are in flight in the processor, and output frames take the
//  same receiver path as plain frames.
//

#if WEBRTC_AVAILABLE && canImport(UIKit) && canImport(AVFoundation)
import Foundation
@preconcurrency import AVFoundation
@preconcurrency import CoreMedia
#if canImport(VideoToolbox)
@preconcurrency import VideoToolbox
#endif
import VideoRenderingKit

#if canImport(VideoToolbox) && !targetEnvironment(simulator)
extension SampleBufferDisplayRenderer {
    /// References a frame while VideoToolbox processes it.
    /// `@unchecked Sendable`: immutable after init; it only carries the buffers across the
    /// processor completion boundary.
    private final class InFlightSuperResolutionFrame: @unchecked Sendable {
        let sourcePixelBuffer: CVPixelBuffer
        let destinationPixelBuffer: CVPixelBuffer
        let arrivalTime: TimeInterval
        let resources: LowLatencySuperResolutionResources
        let attempt: Int

        init(
            sourcePixelBuffer: CVPixelBuffer,
            destinationPixelBuffer: CVPixelBuffer,
            arrivalTime: TimeInterval,
            resources: LowLatencySuperResolutionResources,
            attempt: Int
        ) {
            self.sourcePixelBuffer = sourcePixelBuffer
            self.destinationPixelBuffer = destinationPixelBuffer
            self.arrivalTime = arrivalTime
            self.resources = resources
            self.attempt = attempt
        }
    }

    private static let maxInitializationRetries = 8

    // MARK: - Submission (decode thread)

    /// Non-blocking: either queues the frame into the processor or kicks off session start.
    func submitLowLatencySuperResolutionFrame(
        _ pixelBuffer: CVPixelBuffer,
        arrivalTime: TimeInterval,
        scaleFactor: Float
    ) {
        let width = CVPixelBufferGetWidth(pixelBuffer)
        let height = CVPixelBufferGetHeight(pixelBuffer)

        stateLock.lock()
        guard !llsrFallbackToPlainSampleBuffer else {
            stateLock.unlock()
            return
        }
        let resources = activeLowLatencySuperResolutionResources
        let sessionMatches = resources.map {
            $0.sourceWidth == width && $0.sourceHeight == height && $0.scaleFactor == scaleFactor
        } ?? false
        guard let resources, sessionMatches else {
            let shouldStart = !llsrSessionStartInProgress
            if shouldStart {
                llsrSessionStartInProgress = true
            }
            stateLock.unlock()
            if shouldStart {
                startLowLatencySuperResolutionSession(width: width, height: height, scaleFactor: scaleFactor)
            }
            return
        }

        if llsrInFlightCount >= Self.maxLLSRFramesInFlight {
            if pendingLLSRFrame != nil {
                framesDroppedByCoalescing += 1
            }
            pendingLLSRFrame = (pixelBuffer, arrivalTime)
            drawQueueDepthMax = max(drawQueueDepthMax, llsrInFlightCount + 1)
            stateLock.unlock()
            return
        }
        llsrInFlightCount += 1
        drawQueueDepthMax = max(drawQueueDepthMax, llsrInFlightCount)
        stateLock.unlock()

        processLowLatencySuperResolution(
            pixelBuffer: pixelBuffer,
            arrivalTime: arrivalTime,
            resources: resources,
            attempt: 0
        )
    }

    /// Pre-warms the session for known source dimensions (called when the rung is requested).
    func startLowLatencySuperResolutionSessionIfNeeded(width: Int, height: Int, scaleFactor: Float) {
        stateLock.lock()
        let alreadyMatching = activeLowLatencySuperResolutionResources.map {
            $0.sourceWidth == width && $0.sourceHeight == height && $0.scaleFactor == scaleFactor
        } ?? false
        let shouldStart = !alreadyMatching && !llsrSessionStartInProgress && !llsrFallbackToPlainSampleBuffer
        if shouldStart {
            llsrSessionStartInProgress = true
        }
        stateLock.unlock()
        guard shouldStart else { return }
        startLowLatencySuperResolutionSession(width: width, height: height, scaleFactor: scaleFactor)
    }

    // MARK: - Session lifecycle (utility queue)

    private func startLowLatencySuperResolutionSession(width: Int, height: Int, scaleFactor: Float) {
        updateLowLatencyStatus(
            "warming",
            inputWidth: width,
            inputHeight: height,
            outputWidth: Int((Float(width) * scaleFactor).rounded()),
            outputHeight: Int((Float(height) * scaleFactor).rounded())
        )
        emitTelemetryIfNeeded(force: true)
        let startTime = Date.timeIntervalSinceReferenceDate
        DispatchQueue.global(qos: .userInitiated).async { [weak self] in
            guard let self else { return }
            let result: Result<LowLatencySuperResolutionResources, Error>
            do {
                result = .success(try self.makeLowLatencySuperResolutionResources(
                    width: width,
                    height: height,
                    scaleFactor: scaleFactor
                ))
            } catch {
                result = .failure(error)
            }

            switch result {
            case .success(let resources):
                self.stateLock.lock()
                self.llsrSessionStartInProgress = false
                // Only install if the rung is still wanted for these dimensions.
                let stillWanted: Bool
                if case .vtSuperResolution(let wantedScale) = self.requestedRung,
                   wantedScale == scaleFactor,
                   self.lastSourceWidth == width,
                   self.lastSourceHeight == height {
                    stillWanted = true
                } else {
                    stillWanted = false
                }
                if stillWanted {
                    self.activeLowLatencySuperResolutionResources = resources
                    self.llsrInFlightCount = 0
                    self.pendingLLSRFrame = nil
                }
                self.stateLock.unlock()
                let elapsedMs = (Date.timeIntervalSinceReferenceDate - startTime) * 1_000
                self.streamLog(
                    "[StreamView][SBR \(self.rendererDebugID)] LLSR session ready \(width)x\(height) -> \(resources.outputWidth)x\(resources.outputHeight) scale=\(scaleFactor) in \(Int(elapsedMs)) ms (installed: \(stillWanted))",
                    force: true
                )
            case .failure(let error):
                self.stateLock.lock()
                self.llsrSessionStartInProgress = false
                self.stateLock.unlock()
                self.handleLowLatencySuperResolutionFailure(
                    rung: .vtSuperResolution(scaleFactor: scaleFactor),
                    reason: "session startup failed: \(self.lowLatencyErrorDetails(error))"
                )
            }
        }
    }

    private func makeLowLatencySuperResolutionResources(
        width: Int,
        height: Int,
        scaleFactor: Float
    ) throws -> LowLatencySuperResolutionResources {
        let outputWidth = Int((Float(width) * scaleFactor).rounded())
        let outputHeight = Int((Float(height) * scaleFactor).rounded())

        let configuration = VTLowLatencySuperResolutionScalerConfiguration(
            frameWidth: width,
            frameHeight: height,
            scaleFactor: scaleFactor
        )

        let processor = VTFrameProcessor()
        do {
            try processor.startSession(configuration: configuration)
        } catch {
            throw NSError(
                domain: "StreamView.LowLatencySuperResolution",
                code: (error as NSError).code,
                userInfo: [
                    NSLocalizedDescriptionKey: "startSession failed: \(lowLatencyErrorDetails(error))",
                    NSUnderlyingErrorKey: error as NSError
                ]
            )
        }

        let sourcePixelFormat = kCVPixelFormatType_420YpCbCr8BiPlanarVideoRange
        let resolvedSourceAttributes = try makeResolvedPixelBufferAttributes(
            baseAttributes: configuration.sourcePixelBufferAttributes,
            width: width,
            height: height,
            pixelFormat: sourcePixelFormat,
            label: "llsr-source"
        )
        var sourcePool: CVPixelBufferPool?
        let sourcePoolStatus = CVPixelBufferPoolCreate(kCFAllocatorDefault, nil, resolvedSourceAttributes, &sourcePool)
        guard sourcePoolStatus == kCVReturnSuccess, let sourcePool else {
            processor.endSession()
            throw NSError(
                domain: "StreamView.LowLatencySuperResolution",
                code: Int(sourcePoolStatus),
                userInfo: [NSLocalizedDescriptionKey: "source pool creation failed: \(sourcePoolStatus)"]
            )
        }

        let resolvedDestinationAttributes = try makeResolvedPixelBufferAttributes(
            baseAttributes: configuration.destinationPixelBufferAttributes,
            width: outputWidth,
            height: outputHeight,
            pixelFormat: sourcePixelFormat,
            label: "llsr-destination"
        )
        var destinationPool: CVPixelBufferPool?
        let destinationPoolStatus = CVPixelBufferPoolCreate(kCFAllocatorDefault, nil, resolvedDestinationAttributes, &destinationPool)
        guard destinationPoolStatus == kCVReturnSuccess, let destinationPool else {
            processor.endSession()
            throw NSError(
                domain: "StreamView.LowLatencySuperResolution",
                code: Int(destinationPoolStatus),
                userInfo: [NSLocalizedDescriptionKey: "destination pool creation failed: \(destinationPoolStatus)"]
            )
        }

        var pixelTransferSession: VTPixelTransferSession?
        let pixelTransferStatus = VTPixelTransferSessionCreate(
            allocator: kCFAllocatorDefault,
            pixelTransferSessionOut: &pixelTransferSession
        )
        guard pixelTransferStatus == noErr, let pixelTransferSession else {
            processor.endSession()
            throw NSError(
                domain: "StreamView.LowLatencySuperResolution",
                code: Int(pixelTransferStatus),
                userInfo: [NSLocalizedDescriptionKey: "pixel transfer session creation failed: \(pixelTransferStatus)"]
            )
        }

        stateLock.lock()
        currentLLSRGeneration &+= 1
        let generation = currentLLSRGeneration
        stateLock.unlock()

        return LowLatencySuperResolutionResources(
            sourceWidth: width,
            sourceHeight: height,
            outputWidth: outputWidth,
            outputHeight: outputHeight,
            scaleFactor: scaleFactor,
            generation: generation,
            configuration: configuration,
            processor: processor,
            sourcePool: sourcePool,
            destinationPool: destinationPool,
            pixelTransferSession: pixelTransferSession
        )
    }

    // MARK: - Processing

    private func makeLowLatencySuperResolutionSourceFrame(
        from pixelBuffer: CVPixelBuffer,
        presentationTimeStamp: CMTime,
        resources: LowLatencySuperResolutionResources
    ) throws -> VTFrameProcessorFrame {
        if !lowLatencySourceBufferNeedsCopy(pixelBuffer, requiredAttributes: resources.configuration.sourcePixelBufferAttributes),
           let directSourceFrame = VTFrameProcessorFrame(buffer: pixelBuffer, presentationTimeStamp: presentationTimeStamp) {
            return directSourceFrame
        }

        var preparedSourcePixelBuffer: CVPixelBuffer?
        let sourceStatus = CVPixelBufferPoolCreatePixelBuffer(kCFAllocatorDefault, resources.sourcePool, &preparedSourcePixelBuffer)
        guard sourceStatus == kCVReturnSuccess, let preparedSourcePixelBuffer else {
            throw NSError(
                domain: "StreamView.LowLatencySuperResolution",
                code: Int(sourceStatus),
                userInfo: [NSLocalizedDescriptionKey: "source pixel buffer allocation failed: \(sourceStatus)"]
            )
        }

        let transferStatus = VTPixelTransferSessionTransferImage(resources.pixelTransferSession, from: pixelBuffer, to: preparedSourcePixelBuffer)
        guard transferStatus == noErr else {
            throw NSError(
                domain: "StreamView.LowLatencySuperResolution",
                code: Int(transferStatus),
                userInfo: [NSLocalizedDescriptionKey: "source pixel transfer failed: \(transferStatus)"]
            )
        }
        copyDisplayAttachments(from: pixelBuffer, to: preparedSourcePixelBuffer)
        if !didLogLLSRSourceCopy {
            didLogLLSRSourceCopy = true
            streamLog("[StreamView][SBR \(rendererDebugID)] LLSR source copy inputPF=\(pixelFormatDescription(CVPixelBufferGetPixelFormatType(pixelBuffer))) copiedPF=\(pixelFormatDescription(CVPixelBufferGetPixelFormatType(preparedSourcePixelBuffer)))", force: true)
        }

        guard let copiedSourceFrame = VTFrameProcessorFrame(buffer: preparedSourcePixelBuffer, presentationTimeStamp: presentationTimeStamp) else {
            throw NSError(
                domain: "StreamView.LowLatencySuperResolution",
                code: -1,
                userInfo: [NSLocalizedDescriptionKey: "source frame was not IOSurface-backed"]
            )
        }
        return copiedSourceFrame
    }

    private func processLowLatencySuperResolution(
        pixelBuffer: CVPixelBuffer,
        arrivalTime: TimeInterval,
        resources: LowLatencySuperResolutionResources,
        attempt: Int
    ) {
        let rung = RenderLadderRung.vtSuperResolution(scaleFactor: resources.scaleFactor)
        // The processor only needs monotonic timestamps; arrival time on the host clock serves.
        let processorTimeStamp = CMTime(seconds: arrivalTime, preferredTimescale: 1_000_000)

        let sourceFrame: VTFrameProcessorFrame
        do {
            sourceFrame = try makeLowLatencySuperResolutionSourceFrame(
                from: pixelBuffer,
                presentationTimeStamp: processorTimeStamp,
                resources: resources
            )
        } catch {
            finishInFlight(resources: resources)
            handleLowLatencySuperResolutionFailure(rung: rung, reason: "source frame preparation failed: \(lowLatencyErrorDetails(error))")
            return
        }

        var destinationPixelBuffer: CVPixelBuffer?
        let destinationStatus = CVPixelBufferPoolCreatePixelBuffer(kCFAllocatorDefault, resources.destinationPool, &destinationPixelBuffer)
        guard destinationStatus == kCVReturnSuccess, let destinationPixelBuffer,
              let destinationFrame = VTFrameProcessorFrame(buffer: destinationPixelBuffer, presentationTimeStamp: processorTimeStamp)
        else {
            finishInFlight(resources: resources)
            handleLowLatencySuperResolutionFailure(rung: rung, reason: "destination pixel buffer allocation failed: \(destinationStatus)")
            return
        }

        let parameters = VTLowLatencySuperResolutionScalerParameters(
            sourceFrame: sourceFrame,
            destinationFrame: destinationFrame
        )
        let inFlight = InFlightSuperResolutionFrame(
            sourcePixelBuffer: pixelBuffer,
            destinationPixelBuffer: destinationPixelBuffer,
            arrivalTime: arrivalTime,
            resources: resources,
            attempt: attempt
        )

        resources.processor.process(parameters: parameters) { [weak self] _, error in
            guard let self else { return }
            if let error {
                if self.isLowLatencyInitializationError(error), inFlight.attempt < Self.maxInitializationRetries {
                    // The model is still loading; try this frame again shortly instead of failing the rung.
                    let delay = DispatchTimeInterval.milliseconds(33 * (inFlight.attempt + 1))
                    DispatchQueue.global(qos: .userInitiated).asyncAfter(deadline: .now() + delay) { [weak self] in
                        self?.processLowLatencySuperResolution(
                            pixelBuffer: inFlight.sourcePixelBuffer,
                            arrivalTime: inFlight.arrivalTime,
                            resources: inFlight.resources,
                            attempt: inFlight.attempt + 1
                        )
                    }
                    return
                }
                self.finishInFlight(resources: inFlight.resources)
                self.handleLowLatencySuperResolutionFailure(
                    rung: rung,
                    reason: "process failed: \(self.lowLatencyErrorDetails(error))"
                )
                return
            }
            self.handleLowLatencySuperResolutionSuccess(inFlight, rung: rung)
        }
    }

    /// Decrements the in-flight count and returns the frame that should be submitted next, if any.
    @discardableResult
    private func finishInFlight(resources: LowLatencySuperResolutionResources) -> (pixelBuffer: CVPixelBuffer, arrivalTime: TimeInterval)? {
        stateLock.lock()
        defer { stateLock.unlock() }
        guard activeLowLatencySuperResolutionResources === resources else { return nil }
        llsrInFlightCount = max(0, llsrInFlightCount - 1)
        guard let next = pendingLLSRFrame, llsrInFlightCount < Self.maxLLSRFramesInFlight else { return nil }
        pendingLLSRFrame = nil
        llsrInFlightCount += 1
        return next
    }

    private func handleLowLatencySuperResolutionSuccess(_ inFlight: InFlightSuperResolutionFrame, rung: RenderLadderRung) {
        let resources = inFlight.resources
        stateLock.lock()
        let isCurrentSession = activeLowLatencySuperResolutionResources === resources
        let shouldPromoteDisplay = isCurrentSession && !llsrDisplayActivated
        if shouldPromoteDisplay {
            llsrDisplayActivated = true
        }
        stateLock.unlock()

        let next = finishInFlight(resources: resources)
        guard isCurrentSession else { return }

        copyDisplayAttachments(from: inFlight.sourcePixelBuffer, to: inFlight.destinationPixelBuffer)

        if !didLogFirstLLSRFrame {
            didLogFirstLLSRFrame = true
            streamLog("[StreamView] Low-latency super-resolution first processed frame \(resources.sourceWidth)x\(resources.sourceHeight) -> \(resources.outputWidth)x\(resources.outputHeight)", force: true)
        }

        if shouldPromoteDisplay {
            updateLowLatencyStatus(
                "active",
                inputWidth: resources.sourceWidth,
                inputHeight: resources.sourceHeight,
                outputWidth: resources.outputWidth,
                outputHeight: resources.outputHeight
            )
            reportCandidateReadyIfNeeded(rung)
        }

        enqueue(pixelBuffer: inFlight.destinationPixelBuffer, arrivalTime: inFlight.arrivalTime)
        emitTelemetryIfNeeded()

        if let next {
            processLowLatencySuperResolution(
                pixelBuffer: next.pixelBuffer,
                arrivalTime: next.arrivalTime,
                resources: resources,
                attempt: 0
            )
        }
    }

    private func handleLowLatencySuperResolutionFailure(rung: RenderLadderRung, reason: String) {
        stateLock.lock()
        llsrFallbackToPlainSampleBuffer = true
        llsrDisplayActivated = false
        pendingLLSRFrame = nil
        llsrInFlightCount = 0
        activeLowLatencySuperResolutionResources = nil
        framesFailed += 1
        processingStatus = "failed"
        lastError = reason
        stateLock.unlock()
        streamLog("[StreamView][SBR \(rendererDebugID)] LLSR fallback: \(reason)", force: true)
        reportCandidateFailureIfNeeded(rung, reason: reason)
        emitTelemetryIfNeeded(force: true)
    }
}
