extension MetalVideoRenderer: CAMetalDisplayLinkDelegate {
    /// Runs on the render thread once per display refresh; presents at most one queued frame.
    func metalDisplayLink(_ link: CAMetalDisplayLink, needsUpdate update: CAMetalDisplayLink.Update) {
        let now = CACurrentMediaTime()
        lock.lock()
        lastDisplayLinkTick = now
        let resumedAt = displayLinkResumedAt
        lock.unlock()
        if !didLogDisplayLinkRunning {
            didLogDisplayLinkRunning = true
            streamLog(
                "[MetalRenderer] display link running (first callback \(Int((now - resumedAt) * 1_000)) ms after resume)",
                force: true
            )
        }
        applyPendingRequest()
        guard let frame = dequeueOldestFrame() else {
            emitTelemetryIfNeeded(now: now)
            return
        }
        render(frame, into: update.drawable)
    }

    private func dequeueOldestFrame() -> PendingFrame? {
        lock.lock()
        defer { lock.unlock() }
        guard request.rung != nil, !frameQueue.isEmpty else { return nil }
        return frameQueue.removeFirst()
    }
}

// MARK: - Immediate presentation (low-latency pacing, or a display link that stopped calling back)

extension MetalVideoRenderer {
    /// Presents the newest frame right away, dropping older ones. Render thread only. Used for
    /// `.lowLatency` pacing, and for `.smooth` pacing when the display link has gone silent.
    func presentImmediatelyIfNeeded(displayLinkSilent: Bool = false) {
        applyPendingRequest()
        lock.lock()
        let isImmediate = request.rung != nil && (request.pacing == .lowLatency || displayLinkSilent)
        let frame = isImmediate ? frameQueue.popLast() : nil
        if isImmediate {
            frameQueue.removeAll()
        }
        let shouldLogSilentLink = displayLinkSilent && isImmediate && !didLogSilentDisplayLink
        if shouldLogSilentLink {
            didLogSilentDisplayLink = true
        }
        lock.unlock()
        if shouldLogSilentLink {
            streamLog(
                "[MetalRenderer] display link delivered no callback for \(Int(Self.displayLinkSilenceThreshold * 1_000)) ms; presenting frames on arrival",
                force: true
            )
        }
        guard let frame else { return }
        // Blocks only on this thread, and only when both drawables are still queued for display.
        guard let drawable = metalLayer.nextDrawable() else {
            return
        }
        render(frame, into: drawable)
    }
}

