// MARK: - Present on arrival (only while the display link is not running)

extension MetalVideoRenderer {
    /// Presents the newest queued frame directly, dropping older ones. Render thread only, and
    /// only when no display link is attached: with a link attached its callback owns presentation
    /// and `nextDrawable()` would raise.
    func presentOnArrivalWhileLinkSilent() {
        applyPendingRequest()
        if handleSilentDisplayLink() {
            return
        }
        guard displayLink == nil else { return }
        lock.lock()
        let frame = request.rung != nil ? frameQueue.popLast() : nil
        frameQueue.removeAll()
        lock.unlock()
        guard let frame else { return }
        // Blocks only on this thread, and only when both drawables are still queued for display.
        guard let drawable = metalLayer.nextDrawable() else {
            return
        }
        render(frame, into: drawable, targetPresentationTime: nil)
    }
}

