// MARK: - Immediate presentation (low-latency pacing, or a display link that stopped calling back)

extension MetalVideoRenderer {
    /// Presents the newest frame right away, dropping older ones. Render thread only. Used for
    /// `.lowLatency` pacing, and for `.smooth` pacing while the display link is silent.
    func presentImmediatelyIfNeeded(displayLinkSilent: Bool = false) {
        applyPendingRequest()
        if displayLinkSilent, handleSilentDisplayLink() {
            // A link was just re-armed; its callback owns presentation from here.
            return
        }
        guard displayLink == nil else { return }
        lock.lock()
        let isImmediate = request.rung != nil && (request.pacing == .lowLatency || displayLinkSilent)
        let frame = isImmediate ? frameQueue.popLast() : nil
        if isImmediate {
            frameQueue.removeAll()
        }
        lock.unlock()
        guard let frame else { return }
        // Blocks only on this thread, and only when both drawables are still queued for display.
        guard let drawable = metalLayer.nextDrawable() else {
            return
        }
        render(frame, into: drawable, targetPresentationTime: nil)
    }
}

