/// Anything drawn above the video layer costs a compositor pass (about a frame of latency)
/// and rules out direct scan-out; this shows what is there so it can be kept empty in play.
private func logViewsAboveVideo(reason: String) {
    guard let container else { return }
    var above: [String] = []
    var view: UIView = container
    while let superview = view.superview {
        if let index = superview.subviews.firstIndex(of: view) {
            for sibling in superview.subviews[(index + 1)...] where !sibling.isHidden && sibling.alpha > 0 {
                let background = sibling.backgroundColor.map { "\($0)" } ?? "nil"
                above.append("\(type(of: sibling)) \(Int(sibling.frame.width))x\(Int(sibling.frame.height)) opaque=\(sibling.isOpaque) bg=\(background)")
            }
        }
        view = superview
    }
    streamLog(
        "[StreamView] views above video (\(reason)): \(above.isEmpty ? "none" : above.joined(separator: " | "))",
        force: true
    )
}

