struct WebRTCClientState: Sendable {
    var pendingCandidates: [IceCandidatePayload] = []
    var surfacedOpenDataChannels = Set<DataChannelKind>()
    var surfacedRemoteTrackIDs = Set<ObjectIdentifier>()
    var surfacedRemoteTrackIDsByString = Set<String>()
    var localCandidateList: [IceCandidatePayload] = []
}

/// Lock-protected owner of the live `RTCDataChannel` set so the input send path and `close()`
/// never race on a plain dictionary. `RTCDataChannel` is an Objective-C class without a Sendable
/// annotation, hence `uncheckedState`; every access goes through the lock and callers only use the
/// returned channel for `sendData`/`readyState`, which WebRTC allows from any thread.
final class WebRTCClientDataChannelStore: Sendable {
    private let channels = OSAllocatedUnfairLock<[DataChannelKind: RTCDataChannel]>(uncheckedState: [:])

    /// Installs a new channel set and returns the previous one so the caller can detach delegates.
    @discardableResult
    func replace(with newChannels: [DataChannelKind: RTCDataChannel]) -> [DataChannelKind: RTCDataChannel] {
        channels.withLockUnchecked { current in
            let previous = current
            current = newChannels
            return previous
        }
    }

    func channel(for kind: DataChannelKind) -> RTCDataChannel? {
        channels.withLockUnchecked { $0[kind] }
    }

    func all() -> [DataChannelKind: RTCDataChannel] {
        channels.withLockUnchecked { $0 }
    }
}

