extension WebRTCClientImpl {
    /// Add transceivers and data channels before `createOffer()`.
    /// Mirrors the active XCloud player setup: recvonly audio/video on tvOS plus
    /// the ordered control/input/message/chat data-channel bundle, then pins the
    /// video receiver to H264 so the offer never advertises VP8/VP9/AV1/H265.
    public func applyH264CodecPreferences() {
        guard let peerConnection = ensurePeerConnection() else { return }
#if os(tvOS)
        resetTVOSAudioStartGate(reason: "applyH264CodecPreferences")
#endif

        let audioInit = RTCRtpTransceiverInit()
#if os(tvOS)
        audioInit.direction = .recvOnly
#else
        audioInit.direction = .sendRecv
#endif
        peerConnection.addTransceiver(of: .audio, init: audioInit)

        let videoInit = RTCRtpTransceiverInit()
        videoInit.direction = .recvOnly
        let transceiver = peerConnection.addTransceiver(of: .video, init: videoInit)
        videoTransceiver = transceiver
        if let transceiver {
            applyReceiverVideoCodecPreferences(to: transceiver)
        } else {
            Self.logger.error("addTransceiver(.video) returned nil; codec preferences not applied")
        }

        configureDataChannels(for: peerConnection)
    }

    /// Restricts the video transceiver to H264 (High 640c first, then Constrained Baseline 42e0,
    /// then any other H264 entry) followed by the rtx/red/ulpfec/flexfec helpers in their original
    /// order. Leaves WebRTC defaults untouched when the receiver capabilities are unusable.
    private func applyReceiverVideoCodecPreferences(to transceiver: RTCRtpTransceiver) {
        let capabilities = factory.rtpReceiverCapabilities(forKind: kRTCMediaStreamTrackKindVideo)
        let ordered = Self.orderedH264CodecPreferences(from: capabilities.codecs)
        guard ordered.contains(where: { $0.name.caseInsensitiveCompare("H264") == .orderedSame }) else {
            let advertised = capabilities.codecs.map(\.name).joined(separator: ",")
            Self.logger.warning("Receiver video capabilities contain no H264 entry (\(advertised, privacy: .public)); leaving codec preferences untouched")
            return
        }
        do {
            try transceiver.setCodecPreferences(ordered)
        } catch {
            Self.logger.error("setCodecPreferences failed: \(error.localizedDescription, privacy: .public); leaving codec preferences untouched")
            return
        }
        let summary = ordered.map { codec -> String in
            if let profile = codec.parameters["profile-level-id"] {
                return "\(codec.name)/\(profile)"
            }
            return codec.name
        }.joined(separator: ", ")
        Self.logger.info("Video codec preferences applied: [\(summary, privacy: .public)]")
    }

    static func orderedH264CodecPreferences(from codecs: [RTCRtpCodecCapability]) -> [RTCRtpCodecCapability] {
        let helperNames = ["rtx", "red", "ulpfec", "flexfec-03"]
        func rank(_ codec: RTCRtpCodecCapability) -> Int? {
            let name = codec.name.lowercased()
            if name == "h264" {
                let profile = codec.parameters["profile-level-id"]?.lowercased() ?? ""
                if profile.hasPrefix("640c") { return 0 }
                if profile.hasPrefix("42e0") { return 1 }
                return 2
            }
            if helperNames.contains(name) { return 3 }
            return nil
        }
        // Stable partition: sort by rank only, preserving original order within each tier.
        return codecs
            .enumerated()
            .compactMap { index, codec in rank(codec).map { ($0, index, codec) } }
            .sorted { lhs, rhs in lhs.0 == rhs.0 ? lhs.1 < rhs.1 : lhs.0 < rhs.0 }
            .map(\.2)
    }

    public func createOffer() async throws -> SessionDescription {
        guard let peerConnection = ensurePeerConnection() else { throw WebRTCError.noConnection }

