/// Tears down the active signaling/WebRTC session and clears runtime-owned connection state.
func disconnect() async {
    await teardownActiveConnection()
}

/// Asks the server for a keyframe after the renderer reported a decode failure. Coalesced to one
/// request per `OnDemandKeyframeRateLimiter.minimumInterval` so a burst of failures cannot flood
/// the control channel. Returns true when a request was sent.
@discardableResult
func requestKeyframeOnDemand(reason: String, now: TimeInterval = Date().timeIntervalSinceReferenceDate) async -> Bool {
    guard controlStartupCompleted, let controlChannel else {
        streamLogger.info("On-demand keyframe skipped (control channel not ready): \(reason, privacy: .public)")
        return false
    }
    guard onDemandKeyframeLimiter.shouldRequest(at: now) else {
        streamLogger.debug("On-demand keyframe rate-limited: \(reason, privacy: .public)")
        return false
    }
    streamLogger.info("Requesting keyframe on demand: \(reason, privacy: .public)")
    await controlChannel.requestKeyframe()
    return true
}

