/// Coalesces on-demand keyframe requests so decode-failure bursts produce at most one control-channel
/// message per `minimumInterval`.
struct OnDemandKeyframeRateLimiter: Sendable, Equatable {
    static let minimumInterval: TimeInterval = 2

    private(set) var lastRequestTimestamp: TimeInterval?

    mutating func shouldRequest(at now: TimeInterval) -> Bool {
        if let lastRequestTimestamp, now - lastRequestTimestamp < Self.minimumInterval {
            return false
        }
        lastRequestTimestamp = now
        return true
    }

    mutating func reset() {
        lastRequestTimestamp = nil
    }
}

